import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'
import type { SpawnPaneWorker } from '../types'
import {
  MODEL_COLORS, READ_ONLY_HINT, processTreeArgv, parseProcessTree, startedBelow, isBelow, stayOnTab, answerBoxArgv, type ProcessInfo, askHookSettings, interruptArgv, parseTabIds, pressKeyArgv, typeTextArgv, sessionFactsArgv, parseSessionFacts, type SessionFacts, SETUP_HINTS, TERMINALS, WORKER_MODES, detect, isWindows, killChildren, launcherPs, launcherSh, listPids, parsePids, plan,
  type Terminal,
} from './terminals'
import {
  BLINKS, STANDUP_BRIEF, STATUS_COLORS, STATUS_TEXT, TALLY_VERSION, age, askedQuestion, promptMessage, questionBox, boxKeys, describe, describeProjects, findWorker, sessionDirsByProject, type ProjectActivity, adoptLegacy, emptyTally, isInside, money, projectDirName, statusOf, tallyChunk, modelFamily, RESUME_IDLE_MS,
  reportInstruction, standupPicks, tokenCount, trustKey, withTrust, type Candidate, type Tally, type Worker,
} from './workers'

export const TOOL = 'mcp__spawn-pane__open_agent'
export const LIST_TOOL = 'mcp__spawn-pane__list_workers'
export const CLOSE_TOOL = 'mcp__spawn-pane__close_worker'
export const STOP_TOOL = 'mcp__spawn-pane__stop_worker'
export const ANSWER_TOOL = 'mcp__spawn-pane__answer_worker'
export const PROJECTS_TOOL = 'mcp__spawn-pane__list_projects'

const MODELS = ['haiku', 'sonnet', 'opus', 'fable']
const PANE = 'spawn-pane-workers'
const STORE_KEY = 'workers'
const STANDUP_MAX = 8

const workers = atom({ plugin: 'spawn-pane', key: 'workers' } as const, [] as SpawnPaneWorker[])

type $ = EngineInterface
type Args = {
  folder: string
  brief?: string
  model?: string
  layout?: string
  resume?: boolean
  read_only?: boolean
  worktree?: string
  report?: boolean
}

// --- host facts -------------------------------------------------------------

// Each read is spelled out: the engine lists the variables a plugin reads.
const readEnv = async ($: $) => ({
  SPAWN_PANE_TERMINAL: await $.env.get('SPAWN_PANE_TERMINAL'),
  SPAWN_PANE_ROOT: await $.env.get('SPAWN_PANE_ROOT'),
  SPAWN_PANE_TRUST: await $.env.get('SPAWN_PANE_TRUST'),
  SPAWN_PANE_MODE: await $.env.get('SPAWN_PANE_MODE'),
  SPAWN_PANE_REMOTE: await $.env.get('SPAWN_PANE_REMOTE'),
  SPAWN_PANE_ADOPT: await $.env.get('SPAWN_PANE_ADOPT'),
  SPAWN_PANE_FOCUS: await $.env.get('SPAWN_PANE_FOCUS'),
  TMUX: await $.env.get('TMUX'),
  WEZTERM_PANE: await $.env.get('WEZTERM_PANE'),
  KITTY_WINDOW_ID: await $.env.get('KITTY_WINDOW_ID'),
  WT_SESSION: await $.env.get('WT_SESSION'),
  TERM_PROGRAM: await $.env.get('TERM_PROGRAM'),
  KONSOLE_VERSION: await $.env.get('KONSOLE_VERSION'),
  GNOME_TERMINAL_SCREEN: await $.env.get('GNOME_TERMINAL_SCREEN'),
  VTE_VERSION: await $.env.get('VTE_VERSION'),
  OS: await $.env.get('OS'),
  TEMP: await $.env.get('TEMP'),
  TMPDIR: await $.env.get('TMPDIR'),
  LOCALAPPDATA: await $.env.get('LOCALAPPDATA'),
  USERPROFILE: await $.env.get('USERPROFILE'),
  HOME: await $.env.get('HOME'),
  CLAUDE_CONFIG_DIR: await $.env.get('CLAUDE_CONFIG_DIR'),
})
type HostEnv = Awaited<ReturnType<typeof readEnv>>

const sepOf = (env: HostEnv) => (env.OS === 'Windows_NT' ? '\\' : '/')
const join = (env: HostEnv, ...parts: string[]) =>
  parts.map((p, i) => (i === 0 ? p.replace(/[\\/]+$/, '') : p.replace(/^[\\/]+|[\\/]+$/g, ''))).join(sepOf(env))
const baseName = (path: string) => path.replace(/[\\/]+$/, '').split(/[\\/]/).pop() || path
const parentOf = (path: string) => path.replace(/[\\/]+$/, '').replace(/[\\/][^\\/]*$/, '')

const projectsDir = (env: HostEnv) =>
  join(env, env.CLAUDE_CONFIG_DIR ?? join(env, env.USERPROFILE ?? env.HOME ?? '~', '.claude'), 'projects')

const uuid = () =>
  typeof crypto?.randomUUID === 'function'
    ? crypto.randomUUID()
    : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
        const r = (Math.random() * 16) | 0
        return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16)
      })

// --- the registry -------------------------------------------------------------

// Workers this session has seen close; another session's copy of the list
// must not bring them back.
const closedIds = new Set<string>()

// Only open workers are kept: one whose tab closed, however it closed, leaves
// the list (and the pane) on the next refresh. Every planner session shares
// the stored list, so a save adds what other sessions opened in the meantime
// rather than writing over it.
// One card per running Claude: two planner sessions can each pick up the same
// tab, and a tab the planner opened must not come back as one the user opened.
// A worker the planner opened wins over an adopted one, then the longer-counted.
const onePerSession = (list: Worker[]) => {
  const best = new Map<string, Worker>()
  for (const w of list) {
    const k = w.claudePid ? `pid:${w.claudePid}` : `id:${w.id}`
    const had = best.get(k)
    const better = !had || (had.adopted && !w.adopted) || (!!had.adopted === !!w.adopted && w.costUsd > had.costUsd)
    if (better) best.set(k, w)
  }
  const keep = new Set(best.values())
  return list.filter(w => keep.has(w))
}

const save = async ($: $, list: Worker[]) => {
  for (const w of list) if (w.status === 'closed') closedIds.add(w.id)
  const mine = new Set(list.map(w => w.id))
  const stored = ((await $.store.get(STORE_KEY).catch(() => [])) ?? []) as Worker[]
  const theirs = stored.filter(w => !mine.has(w.id) && !closedIds.has(w.id))
  const kept = onePerSession([...list, ...theirs].filter(w => w.status !== 'closed')).slice(-50)
  await update($, workers, () => kept)
  await $.store.set(STORE_KEY, kept)
  showStatus($, kept)
}

// Cards of workers that are working or need the user blink; this is the
// phase, flipped by a timer that only runs while some card should blink.
let blinkOn = true
let anyBlinking = false

const showStatus = ($: $, list: Worker[]) => {
  const open = list.filter(w => w.status !== 'closed')
  anyBlinking = open.some(w => BLINKS.has(w.status))
  if (open.length === 0) return $.ui.status(undefined)
  const count = (s: Worker['status']) => open.filter(w => w.status === s).length
  const parts = [`${open.length} worker${open.length === 1 ? '' : 's'}`]
  if (count('working')) parts.push(`${count('working')} working`)
  if (count('needs-you')) parts.push(`${count('needs-you')} need you`)
  parts.push(money(list.reduce((sum, w) => sum + w.costUsd, 0)))
  // The engine labels the line with the plugin's name already.
  $.ui.status(parts.join(' · '))
}

// The transcript from byte `offset` on, at most about 3 MB of it. `$.fs.read`
// takes whole files up to 4 MB, and long sessions outgrow that, so anything
// else is read through a small host command that seeks first.
const CHUNK = 3 * 1024 * 1024
const readChunk = async ($: $, env: HostEnv, file: string, offset: number, size: number) => {
  if (offset === 0 && size <= CHUNK) return $.fs.read(file)
  const argv =
    env.OS === 'Windows_NT'
      ? [
          'powershell.exe', '-NoProfile', '-Command',
          `$f=[IO.File]::Open('${file.replace(/'/g, "''")}','Open','Read','ReadWrite');` +
            `[void]$f.Seek(${offset},0);$b=New-Object byte[] ([Math]::Min(${CHUNK},$f.Length-${offset}));` +
            '$n=$f.Read($b,0,$b.Length);$f.Close();[Console]::OutputEncoding=[Text.Encoding]::UTF8;' +
            '[Console]::Out.Write([Text.Encoding]::UTF8.GetString($b,0,$n))',
        ]
      : ['tail', '-c', `+${offset + 1}`, file]
  const ran = await $.process.run(argv, { timeoutMs: 15000 })
  if (ran.exitCode !== 0) throw new Error(`could not read ${file}: ${ran.stderr.trim()}`)
  return ran.stdout
}

const locateTranscript = async ($: $, env: HostEnv, w: Worker) => {
  const file = `${w.sessionId}.jsonl`
  const direct = join(env, projectsDir(env), projectDirName(w.folder), file)
  if (await $.fs.exists(direct)) return direct
  // A worktree session runs from its worktree folder, so look everywhere.
  if (!w.worktree) return undefined
  for (const entry of await $.fs.list(projectsDir(env)).catch(() => [])) {
    if (entry.kind !== 'dir') continue
    const candidate = join(env, projectsDir(env), entry.name, file)
    if (await $.fs.exists(candidate)) return candidate
  }
  return undefined
}

// The process ids running on the host, at most every 10 seconds (or on demand),
// to notice a worker whose tab was closed by hand: its launcher never got to
// write its exit marker.
const LIVENESS_MS = 10000
let lastLiveness = 0
const runningPids = async ($: $, env: HostEnv, force: boolean) => {
  if (!force && Date.now() - lastLiveness < LIVENESS_MS) return undefined
  lastLiveness = Date.now()
  const windows = env.OS === 'Windows_NT'
  const ran = await $.process.run(listPids(windows), { timeoutMs: 10000 }).catch(() => undefined)
  return ran?.exitCode === 0 ? parsePids(windows, ran.stdout) : undefined
}

// The host's process tree, read at most every 3 s and only when a worker has a
// prompt up (it's the costlier of the host checks).
let treeCache: { at: number; tree: Map<string, ProcessInfo[]> } | undefined
async function processTree($: $, env: HostEnv): Promise<Map<string, ProcessInfo[]>> {
  if (treeCache && Date.now() - treeCache.at < 3000) return treeCache.tree
  const ran = await $.process.run(processTreeArgv(env.OS === 'Windows_NT'), { timeoutMs: 15000 }).catch(() => undefined)
  treeCache = { at: Date.now(), tree: parseProcessTree(ran?.exitCode === 0 ? ran.stdout : '') }
  return treeCache.tree
}

// --- Claude Code's own session files ---------------------------------------------
// Every running session writes <config>/sessions/<pid>.json with its session id,
// folder, name and a live status: busy, idle, or waiting (with what for, such
// as "permission prompt"). That's the most direct word on what a session is
// doing, and how open tabs the user started themselves are found.

type LiveSession = {
  pid: string
  sessionId: string
  cwd: string
  name?: string
  status?: string
  waitingFor?: string
  kind?: string
  entrypoint?: string
  startedAt?: number
}

const claudeHome = (env: HostEnv) => env.CLAUDE_CONFIG_DIR ?? join(env, env.USERPROFILE ?? env.HOME ?? '~', '.claude')

async function liveSessions($: $, env: HostEnv): Promise<LiveSession[]> {
  const dir = join(env, claudeHome(env), 'sessions')
  const out: LiveSession[] = []
  for (const f of await $.fs.list(dir).catch(() => [])) {
    if (!/^\d+\.json$/.test(f.name)) continue
    try {
      const d = JSON.parse(await $.fs.read(join(env, dir, f.name)))
      if (d?.sessionId && d?.pid && d?.cwd) out.push({ ...d, pid: String(d.pid) })
    } catch {
      // one being rewritten right now
    }
  }
  return out
}

// Sessions the user hid from the dashboard; they aren't picked up again.
const hiddenIds = new Set<string>()
const HIDDEN_KEY = 'hidden'
let hiddenLoaded = false

// Shows a running session the user opened themselves (with wk, or by typing
// claude): its latest reply's last line and model come from the end of its
// transcript, and its tokens and cost count from now.
async function adoptSession($: $, env: HostEnv, s: LiveSession, terminal: Terminal): Promise<Worker> {
  const transcript = join(env, projectsDir(env), projectDirName(s.cwd), `${s.sessionId}.jsonl`)
  const stat = await $.fs.stat(transcript).catch(() => undefined)
  const size = stat?.size ?? 0
  const from = Math.max(0, size - 262144)
  const tail = size ? await readChunk($, env, transcript, from, size).catch(() => '') : ''
  // Start at a line boundary: the chunk may begin mid-line.
  const t = tallyChunk(emptyTally(), from > 0 ? tail.slice(tail.indexOf('\n') + 1) : tail)
  return {
    id: uuid().slice(0, 6), sessionId: s.sessionId, name: s.name || baseName(s.cwd), folder: s.cwd,
    model: modelFamily(tail) ?? 'own model', readOnly: false, terminal, dir: '', transcript: stat ? transcript : undefined,
    startOffset: size, offset: size, startedAt: s.startedAt ?? Date.now(), status: 'waiting', tokens: 0, costUsd: 0,
    tallyVersion: TALLY_VERSION, adopted: true, claudePid: s.pid,
    summary: t.summary, lastLine: t.lastLine, question: t.question, last: t.last,
  }
}

// The running sessions the user opened themselves that aren't on the list yet:
// interactive CLI sessions (not the desktop app's or headless ones), alive,
// not this planner, not hidden. Off with SPAWN_PANE_ADOPT=off.
// Pairs each open worker with its running Claude, one session file each. By the
// Claude pid once known; a worker the planner opened is first found by its
// session id, and when two tabs run that one conversation, by being the one
// started under its launcher.
async function matchSessions($: $, env: HostEnv, list: Worker[], sessions: LiveSession[]) {
  const matched = new Map<string, LiveSession>()
  const taken = new Set<string>()
  for (const w of list) {
    const s = w.claudePid ? sessions.find(x => x.pid === w.claudePid) : undefined
    if (s && !taken.has(s.pid)) matched.set(w.id, s), taken.add(s.pid)
  }
  for (const w of list) {
    if (matched.has(w.id) || w.adopted || w.status === 'closed') continue
    const candidates = sessions.filter(x => x.sessionId === w.sessionId && !taken.has(x.pid))
    let s = candidates[0]
    if (candidates.length > 1) {
      const launcher = (await $.fs.read(`${w.dir}.pid`).catch(() => '')).trim()
      const tree = await processTree($, env)
      s = candidates.find(c => isBelow(tree, launcher, c.pid)) ?? s
    }
    if (s) matched.set(w.id, s), taken.add(s.pid)
  }
  return { matched, taken }
}

async function adoptable(
  $: $, env: HostEnv, list: Worker[], sessions: LiveSession[], pids: Set<string> | undefined, taken: Set<string>,
) {
  if (!pids || /^(0|off|false|no)$/i.test(env.SPAWN_PANE_ADOPT?.trim() ?? '')) return []
  if (!hiddenLoaded) {
    hiddenLoaded = true
    for (const id of ((await $.store.get(HIDDEN_KEY).catch(() => [])) ?? []) as string[]) hiddenIds.add(id)
  }
  const norm = (path: string) => path.replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()
  const here = norm(await $.session.cwd())
  // A tab the planner just opened may not have its session file yet: leave its
  // conversation alone until it's matched.
  const launching = new Set(list.filter(w => w.status !== 'closed' && !w.adopted && !w.claudePid).map(w => w.sessionId))
  const terminal = detect(name => (env as Record<string, string | undefined>)[name]) ?? (env.OS === 'Windows_NT' ? 'windows-terminal' : 'tmux')
  const found: Worker[] = []
  for (const s of sessions) {
    if (s.kind !== 'interactive' || s.entrypoint !== 'cli' || !pids.has(s.pid)) continue
    if (taken.has(s.pid) || launching.has(s.sessionId) || hiddenIds.has(s.sessionId)) continue
    if (norm(s.cwd) === here) continue
    found.push(await adoptSession($, env, s, terminal as Terminal))
  }
  return found
}

async function refreshOne(
  $: $, env: HostEnv, w: Worker, pids: Set<string> | undefined, now: number, live: LiveSession | undefined,
): Promise<Worker> {
  if (live) w = { ...w, claudePid: live.pid }
  if (w.adopted) {
    // Not ours to close: it's gone when its Claude is.
    if (pids && w.claudePid && !pids.has(w.claudePid)) return { ...w, status: 'closed' }
  } else {
    if (await $.fs.exists(`${w.dir}.exited`)) return { ...w, status: 'closed' }
    if (pids) {
      const pid = (await $.fs.read(`${w.dir}.pid`).catch(() => '')).trim()
      if (/^\d+$/.test(pid) && !pids.has(pid)) return { ...w, status: 'closed' }
    }
  }
  const transcript = w.transcript ?? (await locateTranscript($, env, w))
  const stat = transcript ? await $.fs.stat(transcript).catch(() => undefined) : undefined
  if (!transcript || !stat) return w

  // Count what the transcript gained since the last read, a chunk at a time.
  w = adoptLegacy(w, stat.size)
  // Counted by an older version, which tracked less (background tasks, say):
  // count it again from where its own work began.
  if (w.tallyVersion !== TALLY_VERSION)
    w = { ...w, tallyVersion: TALLY_VERSION, offset: w.startOffset, tokens: 0, costUsd: 0, lastId: undefined, background: undefined }
  let t: Tally = {
    offset: w.offset ?? w.startOffset, tokens: w.tokens, costUsd: w.costUsd, lastId: w.lastId, last: w.last,
    summary: w.summary, lastLine: w.lastLine, pending: w.pending, question: w.question, background: w.background,
  }
  if (stat.size < t.offset) t = emptyTally() // rewritten from scratch
  while (stat.size > t.offset) {
    const before = t.offset
    t = tallyChunk(t, await readChunk($, env, transcript, t.offset, stat.size))
    if (t.offset === before) break // only a line still being written
  }
  // A resumed conversation with nothing added yet is idle at its prompt, not starting.
  const resumedIdle = t.last === undefined && w.startOffset > 0 && now - w.startedAt > RESUME_IDLE_MS
  // The worker's hook marked a permission prompt, and nothing has been written
  // to the transcript since (approving, denying or stopping all write to it).
  const marker = w.adopted ? undefined : await $.fs.stat(`${w.dir}.asking`).catch(() => undefined)
  // While a prompt is on screen Claude hasn't written the tool call yet, so the
  // marker being newer than the transcript says a prompt went up. Once the
  // user approves, the transcript stays silent until the command finishes,
  // but the command itself shows up as a process started since the prompt.
  const prompted = marker !== undefined && marker.mtimeMs >= stat.mtimeMs
  const launcherPid = prompted ? (await $.fs.read(`${w.dir}.pid`).catch(() => '')).trim() : ''
  const approved = prompted && /^\d+$/.test(launcherPid) && startedBelow(await processTree($, env), launcherPid, marker!.mtimeMs)
  const asking = prompted && !approved
  const markerText = asking ? await $.fs.read(`${w.dir}.asking`).catch(() => '') : ''
  // Claude's multiple-choice question box is answered with a choice, not a yes.
  let box = asking ? questionBox(markerText) : undefined
  const asked = asking && !box ? promptMessage(markerText) : undefined
  // A reply that ends on a question is waiting for the user's answer.
  let status = resumedIdle ? 'waiting' : askedQuestion(statusOf(t.last, now - stat.mtimeMs, asking), t.question, t.background?.length ?? 0)
  let pending = asking && !box ? (asked ?? t.pending ?? 'a permission prompt') : undefined
  if (box) status = 'needs-you'
  // Claude's own word on the session beats reading the transcript for signs:
  // waiting is a prompt or dialog on screen, busy is a turn or agents running,
  // idle is sitting at the prompt (unless a reply asked something, or
  // background commands it can't see are still going), and shell is idle with
  // a background command of its own running.
  if (live?.status === 'waiting') {
    status = 'needs-you'
    // "input needed" is a question box; without the hook's marker (a tab the
    // user opened) its question and choices aren't known.
    if (live.waitingFor === 'input needed') box ??= { question: 'a multiple-choice question' }
    if (!box) pending ??= t.question ? undefined : (live.waitingFor ?? 'your input')
  } else if (live?.status === 'busy' || live?.status === 'shell') {
    // shell: its turn is over but a background command it started still runs.
    status = 'working'
    pending = undefined
    box = undefined
  } else if (live?.status === 'idle' && t.last !== undefined) {
    status = t.question ? 'needs-you' : (t.background?.length ?? 0) > 0 ? 'working' : 'waiting'
    pending = undefined
    box = undefined
  }
  return {
    ...w, transcript, offset: t.offset, lastId: t.lastId, last: t.last,
    status: status as Worker['status'],
    tokens: t.tokens, costUsd: t.costUsd, summary: t.summary,
    lastLine: t.lastLine, pending,
    question: box ? box.question : t.last === 'turn-end' || t.last === 'assistant-text' ? t.question : undefined,
    box: box ? true : undefined,
    choices: box?.choices,
    background: t.background,
  }
}

let refreshing = false
const refresh = async ($: $, force = false) => {
  if (refreshing) return
  refreshing = true
  try {
    const list = await read($, workers)
    const env = await readEnv($)
    const now = Date.now()
    const pids = await runningPids($, env, force)
    const sessions = await liveSessions($, env)
    const { matched, taken } = await matchSessions($, env, list, sessions)
    const found = await adoptable($, env, list, sessions, pids, taken)
    if (!found.length && !list.some(w => w.status !== 'closed')) return
    const next: Worker[] = []
    // One worker that can't be read must not hold back the others.
    for (const w of [...list, ...found]) {
      const live = matched.get(w.id) ?? sessions.find(s => s.pid === w.claudePid)
      next.push(w.status === 'closed' ? w : await refreshOne($, env, w, pids, now, live).catch(() => w))
    }
    await save($, next)
  } finally {
    refreshing = false
  }
}

// --- opening and closing a worker -----------------------------------------------

type Opened = { worker: Worker; note?: string }

const workspaceRoot = async ($: $, env: HostEnv) => env.SPAWN_PANE_ROOT ?? parentOf(await $.session.cwd())

// Accepts the "Do you trust this folder?" dialog ahead of time, the way
// answering Yes would, for folders inside the workspace. Answers a note when
// the worker will still ask.
async function ensureTrust($: $, env: HostEnv, folder: string): Promise<string | undefined> {
  if (env.SPAWN_PANE_TRUST?.trim().toLowerCase() === 'off') return undefined
  const root = await workspaceRoot($, env)
  if (!isInside(root, folder, env.OS === 'Windows_NT'))
    return `${folder} is outside ${root}, so the worker will ask whether to trust it`

  const top = await $.process.run(['git', '-C', folder, 'rev-parse', '--show-toplevel'], { timeoutMs: 10000 }).catch(() => undefined)
  const key = trustKey(top?.exitCode === 0 && top.stdout.trim() ? top.stdout : folder)
  const home = env.CLAUDE_CONFIG_DIR ?? env.USERPROFILE ?? env.HOME ?? '~'
  const config = join(env, home, '.claude.json')

  // Other Claude sessions write this file too: each pass reads it fresh and
  // finds the key trusted (done) or writes it; a pass that sees the change
  // gone again (another session wrote over it) writes it once more.
  for (let attempt = 0; attempt < 3; attempt++) {
    const text = await $.fs.read(config).catch(() => undefined)
    if (text === undefined) return 'could not read the Claude config, so the worker will ask about trust'
    const next = withTrust(text, key)
    if (next === undefined) return undefined
    await $.fs.write(config, next)
  }
  return 'could not record trust, so the worker may ask about it'
}

const openWorker = async ($: $, args: Args): Promise<Opened | { deny: string }> => {
  const env = await readEnv($)
  const folder = args.folder.length > 1 ? args.folder.replace(/[\\/]+$/, '') : args.folder
  // A resumed conversation keeps its own model unless one is asked for.
  const model = MODELS.includes(args.model ?? '') ? args.model! : args.resume ? undefined : 'sonnet'

  const override = env.SPAWN_PANE_TERMINAL?.trim().toLowerCase()
  if (override && !(TERMINALS as readonly string[]).includes(override))
    return { deny: `SPAWN_PANE_TERMINAL=${override} is not a terminal spawn-pane knows. Use one of: ${TERMINALS.join(', ')}.` }
  const terminal = (override as Terminal | undefined) ?? detect(name => (env as Record<string, string | undefined>)[name])
  if (!terminal)
    return {
      deny:
        `spawn-pane could not tell which terminal this is. Supported: ${TERMINALS.join(', ')}. ` +
        'Set SPAWN_PANE_TERMINAL to one of them, or run Claude Code inside tmux.',
    }

  const stat = await $.fs.stat(folder).catch(() => undefined)
  if (stat?.kind !== 'dir') return { deny: `No such folder: ${folder}` }
  if (args.worktree !== undefined && !/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(args.worktree))
    return { deny: `Worktree names are letters, digits, '.', '_' and '-': ${args.worktree}` }

  // Continue the folder's last conversation: the newest session Claude Code
  // has for it. The worker counts only what it adds, from the transcript's
  // current end.
  const notes: string[] = []
  let session: [string, string] = ['--session-id', uuid()]
  let startOffset = 0
  let sessionFile: string | undefined
  if (args.resume) {
    // The user's own last session there: not one a worker ran (its brief
    // marks it), and the one Claude last answered in, since resuming touches
    // a file without any work being done in it.
    const dir = join(env, projectsDir(env), projectDirName(folder))
    const files: { file: string; name: string; mtimeMs: number; size: number }[] = []
    for (const f of await $.fs.list(dir).catch(() => []))
      if (f.name.endsWith('.jsonl')) files.push({ file: join(env, dir, f.name), name: f.name, mtimeMs: f.mtimeMs, size: f.size })
    const recent = files.sort((a, b) => b.mtimeMs - a.mtimeMs).slice(0, 12)
    const facts = await sessionFacts($, env, recent.map(f => f.file))
    const answered = (f: (typeof files)[number]) => facts.get(f.file)?.lastAnswerMs ?? 0
    const pick = recent.filter(f => !facts.get(f.file)?.worker).sort((a, b) => answered(b) - answered(a))[0]
    if (pick) {
      session = ['--resume', pick.name.slice(0, -'.jsonl'.length)]
      // The worker counts only what it adds: from the transcript's end now.
      startOffset = (await $.fs.stat(pick.file).catch(() => undefined))?.size ?? pick.size
      sessionFile = pick.file
    }
    notes.push(
      pick
        ? 'it reopened the last conversation the user had there, where they left off'
        : 'the user has no earlier conversation of their own there, so it opened a new one',
    )
  }
  if (!args.brief?.trim() && !args.resume) return { deny: 'A brief is required unless resuming a conversation.' }

  // A resumed conversation keeps its own model, so find which that is for the
  // tab color and the list: the newest model in its transcript, else settings.
  let shownModel = model
  if (!shownModel && sessionFile) {
    const tail = await readChunk($, env, sessionFile, Math.max(0, startOffset - 256 * 1024), startOffset).catch(() => '')
    shownModel = modelFamily(tail)
    if (!shownModel) {
      const home = env.CLAUDE_CONFIG_DIR ?? join(env, env.USERPROFILE ?? env.HOME ?? '~', '.claude')
      shownModel = modelFamily(await $.fs.read(join(env, home, 'settings.json')).catch(() => ''))
    }
  }

  const trustNote = await ensureTrust($, env, folder).catch(() => 'could not record trust, so the worker may ask about it')
  if (trustNote) notes.push(trustNote)

  const asPane = args.layout === 'pane'
  const report = args.report !== false
  const brief = args.brief?.trim()
    ? [
        args.brief.trim(),
        `(You were opened in your own terminal ${asPane ? 'pane' : 'tab'} by the user's planner session. ` +
          'Answer the user here directly; they will read it here.)',
        ...(args.read_only ? [READ_ONLY_HINT] : []),
        ...(report ? [reportInstruction()] : []),
      ].join('\n\n')
    : ''

  // Its own id, not the conversation's: resuming a folder twice must not give
  // two workers one name.
  const id = uuid().slice(0, 6)
  const name = args.worktree ? `${baseName(folder)}:${args.worktree}` : baseName(folder)
  const windows = isWindows(terminal)
  const temp = windows ? env.TEMP ?? $.plugin.root : (env.TMPDIR ?? '/tmp').replace(/\/+$/, '')
  const base = join(env, temp, `spawn-pane-${id}-${Date.now()}`)
  const readOnly = args.read_only === true
  const mode = WORKER_MODES.find(m => m.toLowerCase() === env.SPAWN_PANE_MODE?.trim().toLowerCase())
  // Remote Control is the user's choice (it puts the session on their phone).
  const remote = /^(1|on|true|yes)$/i.test(env.SPAWN_PANE_REMOTE?.trim() ?? '')
  const launch = { folder, brief, model, session, name, readOnly, mode, remote, worktree: args.worktree, base }
  const script = `${base}${windows ? '.ps1' : '.sh'}`
  await $.fs.write(script, windows ? launcherPs(launch) : launcherSh(launch))
  await $.fs.write(`${base}.settings.json`, askHookSettings(base, windows))

  const wtPath = `${env.LOCALAPPDATA ?? ''}\\Microsoft\\WindowsApps\\wt.exe`
  const opened = plan({ terminal, folder, script, asPane, wtPath, title: name, color: shownModel && MODEL_COLORS[shownModel] })
  // A new Windows Terminal tab takes focus; go back to where the user was typing.
  const stay = terminal === 'windows-terminal' && !opened.asPane && env.SPAWN_PANE_FOCUS?.trim().toLowerCase() !== 'new'
  const ran = await $.process
    .run(stay ? stayOnTab(opened.argv) : opened.argv, { timeoutMs: 20000 })
    .catch((err: Error) => ({ exitCode: -1, stderr: err.message }))
  if (ran.exitCode !== 0) {
    const hint = SETUP_HINTS[terminal] ? ` (${SETUP_HINTS[terminal]})` : ''
    return { deny: `Could not open a ${terminal} ${asPane ? 'pane' : 'tab'}: ${ran.stderr.trim()}${hint}` }
  }
  if (opened.note) notes.push(opened.note)

  const worker: Worker = {
    id, sessionId: session[1], name, folder, model: shownModel ?? 'own model', readOnly, worktree: args.worktree,
    terminal, dir: base, startOffset, startedAt: Date.now(), status: 'starting', tokens: 0, costUsd: 0,
  }
  await save($, [...(await read($, workers)), worker])
  // Seats only where a pane can (an interactive session, wide enough); fine to miss.
  $.ui.open({ id: PANE, title: 'Workers' }).catch(() => undefined)
  return { worker, note: notes.join('; ') || undefined }
}

// Where to press keys for a worker: its launcher (and, on posix terminals, its
// tab's ids), or for a session the user opened, its Claude process.
const tabOf = async ($: $, w: Worker) =>
  w.adopted
    ? { pid: w.claudePid ?? '', ids: {} as ReturnType<typeof parseTabIds> }
    : {
        pid: (await $.fs.read(`${w.dir}.pid`).catch(() => '')).trim(),
        ids: parseTabIds(await $.fs.read(`${w.dir}.term`).catch(() => '')),
      }

const closeWorker = async ($: $, w: Worker) => {
  if (w.adopted) {
    // The user opened that tab; closing it here only takes it off the list.
    hiddenIds.add(w.sessionId)
    await $.store.set(HIDDEN_KEY, [...hiddenIds].slice(-200)).catch(() => undefined)
    return `${w.name}: removed from the dashboard (its tab stays open)`
  }
  await $.fs.write(`${w.dir}.close`, 'close')
  const pid = (await $.fs.read(`${w.dir}.pid`).catch(() => '')).trim()
  if (!/^\d+$/.test(pid)) return `${w.name}: no process id recorded, close its tab by hand`
  await $.process.run(killChildren(w.terminal as Terminal, pid), { timeoutMs: 15000 }).catch(() => undefined)
  return `${w.name}: closed`
}

// Reads, for each transcript, when Claude last answered there and whether a
// worker ran it (see sessionFactsArgv), in one host command.
async function sessionFacts($: $, env: HostEnv, files: string[]): Promise<Map<string, SessionFacts>> {
  if (files.length === 0) return new Map()
  const ran = await $.process
    .run(sessionFactsArgv(env.OS === 'Windows_NT'), { stdin: files.join('\n') + '\n', timeoutMs: 30000 })
    .catch(() => undefined)
  return parseSessionFacts(ran?.stdout ?? '')
}

// Presses Esc in the worker's tab: Claude ends its current turn (or declines
// the permission prompt it's waiting on) and the session stays open.
async function stopWorker($: $, w: Worker): Promise<string> {
  const { pid, ids } = await tabOf($, w)
  const argv = /^\d+$/.test(pid) ? interruptArgv(w.terminal as Terminal, pid, ids) : undefined
  if (!argv) return `${w.name}: can't press Esc in a ${w.terminal} tab from outside; press Esc in that tab to stop it`
  const ran = await $.process.run(argv, { timeoutMs: 15000 }).catch(() => undefined)
  return ran?.exitCode === 0 ? `${w.name}: stopped (its session is still open)` : `${w.name}: could not reach its tab to stop it`
}

// Answers the permission prompt a worker is waiting on, from the dashboard or
// the planner: Enter takes its highlighted first answer (Yes), Esc declines.
async function answerWorker($: $, w: Worker, answer: 'approve' | 'deny'): Promise<string> {
  const { pid, ids } = await tabOf($, w)
  const argv = /^\d+$/.test(pid) ? pressKeyArgv(w.terminal as Terminal, pid, ids, answer === 'approve' ? 'enter' : 'escape') : undefined
  const what = w.pending ?? 'its request'
  if (!argv) return `${w.name}: can't answer a ${w.terminal} tab from outside; answer in that tab`
  const ran = await $.process.run(argv, { timeoutMs: 15000 }).catch(() => undefined)
  if (ran?.exitCode !== 0) return `${w.name}: could not reach its tab`
  return answer === 'approve' ? `${w.name}: approved ${what}` : `${w.name}: declined ${what}`
}

// Types a reply into the worker's tab and presses Enter: "continue" from the
// dashboard, or whatever the user asked the planner to tell it.
async function replyToWorker($: $, w: Worker, text: string): Promise<string> {
  const { pid, ids } = await tabOf($, w)
  const argv = /^\d+$/.test(pid) ? typeTextArgv(w.terminal as Terminal, pid, ids, text) : undefined
  if (!argv) return `${w.name}: can't type into a ${w.terminal} tab from outside; reply in that tab`
  const ran = await $.process.run(argv, { timeoutMs: 15000 }).catch(() => undefined)
  return ran?.exitCode === 0 ? `${w.name}: replied "${text}"` : `${w.name}: could not reach its tab`
}

// Answers the question box a worker shows: a choice by its number, or any
// other answer through "type something".
async function answerBox($: $, w: Worker, text: string): Promise<string> {
  if (!w.choices) return `${w.name}: its question can't be answered from here; answer it in its tab`
  const { pid, ids } = await tabOf($, w)
  const keys = boxKeys(w.choices, text)
  const argv = /^\d+$/.test(pid) ? answerBoxArgv(w.terminal as Terminal, pid, ids, keys) : undefined
  if (!argv) return `${w.name}: can't answer a ${w.terminal} tab from outside; answer in that tab`
  const ran = await $.process.run(argv, { timeoutMs: 15000 }).catch(() => undefined)
  if (ran?.exitCode !== 0) return `${w.name}: could not reach its tab`
  return keys.type ? `${w.name}: answered "${keys.type}"` : `${w.name}: chose "${w.choices[Number(keys.pick) - 1]}"`
}

// Closes these workers and drops them from the list, for close_worker and the
// pane's close buttons alike.
async function closeAll($: $, targets: Worker[]): Promise<string[]> {
  const lines: string[] = []
  for (const w of targets) lines.push(await closeWorker($, w))
  const ids = new Set(targets.map(w => w.id))
  await save($, (await read($, workers)).map(w => (ids.has(w.id) ? { ...w, status: 'closed' as const } : w)))
  return lines
}

// --- the engine's side ---------------------------------------------------------

const OPEN_DESCRIPTION =
  'Opens a new terminal tab (or, if the user asks, a side-by-side pane) in `folder` and ' +
  'starts a Claude Code worker there whose first prompt is `brief`. The worker answers the ' +
  'user in that tab. Use it when the user asks for work or a status report about a specific ' +
  'folder. Write `brief` as a self-contained instruction: what the user wants, why, and what ' +
  "to report. Use read_only for status checks and reviews, resume to pick up the folder's " +
  'last conversation, and worktree to run several workers on one repository without them ' +
  "touching each other's files. By default the worker ends its first reply with a one-line " +
  'summary that list_workers shows here.'

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.tool.register({
      name: 'open_agent',
      description: OPEN_DESCRIPTION,
      inputSchema: {
        type: 'object',
        properties: {
          folder: { type: 'string', description: 'Absolute path of the folder the worker works in.' },
          brief: { type: 'string', description: 'The first prompt for the worker. Optional only with resume.' },
          model: { type: 'string', enum: MODELS, description: 'Defaults to sonnet.' },
          layout: { type: 'string', enum: ['tab', 'pane'], description: 'Defaults to tab.' },
          resume: { type: 'boolean', description: "Continue the folder's last conversation instead of a new one." },
          read_only: { type: 'boolean', description: 'Plan mode: the worker can look but not change anything.' },
          worktree: { type: 'string', description: 'Run in a new git worktree with this name (letters, digits, -).' },
          report: { type: 'boolean', description: 'Ask for a one-line summary for list_workers. Defaults to true.' },
        },
        required: ['folder'],
        additionalProperties: false,
      },
    })
    await $.tool.register({
      name: 'list_workers',
      description:
        'Lists the workers spawn-pane opened: status (working, waiting for the user, needs ' +
        'the user, closed), age, tokens, estimated cost and each one-line summary. Use it ' +
        'when the user asks how their workers are doing or what they found.',
      inputSchema: { type: 'object', properties: {}, additionalProperties: false },
    })
    await $.tool.register({
      name: 'stop_worker',
      description:
        "Stops what a worker is doing, the way pressing Esc in its tab would: Claude ends its " +
        "current turn (or declines the permission prompt it's waiting on) and the session stays " +
        'open for the user. By name, id, or all busy workers. Use it for "stop X"; closing the ' +
        'tab is close_worker.',
      inputSchema: {
        type: 'object',
        properties: {
          worker: { type: 'string', description: 'Name or id, as list_workers shows it.' },
          all: { type: 'boolean', description: 'Stop every worker that is working or needs the user.' },
        },
        additionalProperties: false,
      },
    })
    await $.tool.register({
      name: 'answer_worker',
      description:
        'Answers what a worker is waiting on (list_workers shows it). For a permission ' +
        'prompt: approve presses Enter in its tab, choosing Yes; deny presses Esc. For a ' +
        'question it asked: reply types `text` into its tab and presses Enter ("continue", ' +
        'or the user\'s answer in their words). Use it when the user says to approve, deny, ' +
        'continue, or tell a worker something.',
      inputSchema: {
        type: 'object',
        properties: {
          worker: { type: 'string', description: 'Name or id, as list_workers shows it.' },
          answer: { type: 'string', enum: ['approve', 'deny', 'reply'] },
          text: { type: 'string', description: 'With reply: what to type, one line.' },
        },
        required: ['worker', 'answer'],
        additionalProperties: false,
      },
    })
    await $.tool.register({
      name: 'close_worker',
      description:
        'Closes a worker tab spawn-pane opened, by its name (the folder name), its id, or ' +
        'all of them. Ends its Claude session.',
      inputSchema: {
        type: 'object',
        properties: {
          worker: { type: 'string', description: 'Name or id, as list_workers shows it.' },
          all: { type: 'boolean', description: 'Close every open worker.' },
        },
        additionalProperties: false,
      },
    })
    await $.tool.register({
      name: 'list_projects',
      description:
        "Lists the project folders in the user's workspace (absolute paths), most recently used " +
        'first, with when each last had a Claude session and a git commit. Use it to match a ' +
        'name like "api" to its folder, and for requests like "the last five projects I worked ' +
        'on". Archives and backups are listed apart. Reads no file contents: anything about ' +
        "what's inside a project is a worker's job.",
      inputSchema: { type: 'object', properties: {}, additionalProperties: false },
    })
    await $.command.register({
      name: 'standup',
      description: 'Open a read-only status tab for every project with commits in the last N days (default 3)',
    })
    await $.command.register({ name: 'workers', description: 'Show the spawn-pane workers pane' })

    const stored = ((await $.store.get(STORE_KEY)) ?? []) as Worker[]
    await update($, workers, () => stored)
    showStatus($, stored)
    $.clock.every(4000, () => void refresh($).catch(() => undefined))
    $.clock.every(600, () => {
      if (!anyBlinking && blinkOn) return
      blinkOn = anyBlinking ? !blinkOn : true
      $.ui.invalidate('ui.render')
    })
    return next(e)
  })

  // Each message to the planner first checks which worker tabs are still
  // there, so tabs closed by hand leave the list before the planner answers.
  on('prompt.submit', async ($, e, next) => {
    await refresh($, true).catch(() => undefined)
    return next(e)
  })

  on('tool.call', { tool: TOOL }, async ($, e) => {
    const out = await openWorker($, e as unknown as Args)
    if ('deny' in out) return { deny: out.deny }
    const { worker: w, note } = out
    $.ui.toast(`Opened ${w.model} worker in ${w.name}`)
    return {
      result:
        `Opened ${w.name} [${w.id}] with ${w.model}${w.readOnly ? ' (read-only)' : ''} in a new ` +
        `${w.terminal} tab. It will answer the user there.` + (note ? ` Note: ${note}.` : ''),
    }
  })

  on('tool.call', { tool: LIST_TOOL }, async $ => {
    await refresh($, true)
    const list = await read($, workers)
    const now = Date.now()
    return { result: list.length ? list.map(w => describe(w, now)).join('\n') : 'No workers open.' }
  })

  on('tool.call', { tool: PROJECTS_TOOL }, async $ => {
    const env = await readEnv($)
    const root = await workspaceRoot($, env)
    const here = (await $.session.cwd()).replace(/[\\/]+$/, '').toLowerCase()
    const folders = (await $.fs.list(root).catch(() => []))
      .filter(e => e.kind === 'dir' && !e.name.startsWith('.'))
      .map(e => join(env, root, e.name))
      .filter(path => path.toLowerCase() !== here)
    if (folders.length === 0) return { result: `No project folders in ${root}.` }

    // When each was last worked on: when Claude last answered in a session in
    // it or under it (its six most recently touched transcripts are
    // checked), and its last git commit.
    const sessionDirs = (await $.fs.list(projectsDir(env)).catch(() => [])).filter(e => e.kind === 'dir').map(e => e.name)
    const owned = sessionDirsByProject(folders, sessionDirs)
    const candidates = new Map<string, string[]>()
    for (const path of folders) {
      const files: { file: string; mtimeMs: number }[] = []
      for (const dir of owned.get(path) ?? []) {
        const at = join(env, projectsDir(env), dir)
        for (const f of await $.fs.list(at).catch(() => []))
          if (f.name.endsWith('.jsonl')) files.push({ file: join(env, at, f.name), mtimeMs: f.mtimeMs })
      }
      candidates.set(path, files.sort((a, b) => b.mtimeMs - a.mtimeMs).slice(0, 6).map(f => f.file))
    }
    // Sessions a worker ran don't count as the user working there.
    const facts = await sessionFacts($, env, [...candidates.values()].flat())

    const items: ProjectActivity[] = []
    for (const path of folders) {
      const times = (candidates.get(path) ?? [])
        .map(f => facts.get(f))
        .filter(f => f !== undefined && !f.worker)
        .map(f => f!.lastAnswerMs)
        .filter((t): t is number => t !== undefined)
      const log = await $.process.run(['git', '-C', path, 'log', '-1', '--format=%ct'], { timeoutMs: 10000 }).catch(() => undefined)
      const sec = log?.exitCode === 0 ? parseInt(log.stdout.trim(), 10) : NaN
      items.push({
        path,
        lastSessionMs: times.length ? Math.max(...times) : undefined,
        lastCommitMs: Number.isFinite(sec) ? sec * 1000 : undefined,
      })
    }
    return { result: describeProjects(root, items, Date.now()) }
  })

  on('tool.call', { tool: ANSWER_TOOL }, async ($, e) => {
    const args = e as unknown as { worker: string; answer: 'approve' | 'deny' | 'reply'; text?: string }
    const w = findWorker(await read($, workers), args.worker)
    if (!w) return { deny: `No open worker matches "${args.worker}".` }
    if (args.answer === 'reply') {
      if (!args.text?.trim()) return { deny: 'A reply needs text.' }
      if (w.pending) return { deny: `${w.name} is waiting on a permission prompt; approve or deny it first.` }
      if (w.box) return { result: await answerBox($, w, args.text) }
      return { result: await replyToWorker($, w, args.text) }
    }
    if (w.box) return { deny: `${w.name} is asking a question, not for permission; reply with the answer${w.choices ? ` (${w.choices.join(' / ')}, or anything else)` : ''}.` }
    if (!w.pending) return { deny: `${w.name} isn't waiting on a permission prompt.` }
    return { result: await answerWorker($, w, args.answer === 'deny' ? 'deny' : 'approve') }
  })

  on('tool.call', { tool: STOP_TOOL }, async ($, e) => {
    const args = e as unknown as { worker?: string; all?: boolean }
    const list = await read($, workers)
    const targets = args.all
      ? list.filter(w => BLINKS.has(w.status))
      : [findWorker(list, args.worker ?? '')].filter((w): w is Worker => w !== undefined)
    if (targets.length === 0) return { deny: `No open worker matches "${args.worker ?? ''}".` }
    const lines: string[] = []
    for (const w of targets) lines.push(await stopWorker($, w))
    return { result: lines.join('\n') }
  })

  on('tool.call', { tool: CLOSE_TOOL }, async ($, e) => {
    const args = e as unknown as { worker?: string; all?: boolean }
    const list = await read($, workers)
    const targets = args.all
      ? list.filter(w => w.status !== 'closed')
      : [findWorker(list, args.worker ?? '')].filter((w): w is Worker => w !== undefined)
    if (targets.length === 0) return { deny: `No open worker matches "${args.worker ?? ''}".` }
    const lines = await closeAll($, targets)
    return { result: lines.join('\n') }
  })

  on('command.run', { command: 'workers' }, async $ => {
    const opened = await $.ui.open({ id: PANE, title: 'Workers', focus: true }).then(() => true, () => false)
    if (opened) return { text: 'Workers pane opened.' }
    const list = await read($, workers)
    const now = Date.now()
    return { text: list.length ? list.map(w => describe(w, now)).join('\n') : 'No workers open.' }
  })

  on('command.run', { command: 'standup' }, async ($, e) => {
    const days = Math.max(1, parseInt(e.args, 10) || 3)
    const env = await readEnv($)
    const here = await $.session.cwd()
    const root = await workspaceRoot($, env)
    const candidates: Candidate[] = []
    for (const entry of await $.fs.list(root).catch(() => [])) {
      if (entry.kind !== 'dir' || /^[._]/.test(entry.name)) continue
      const path = join(env, root, entry.name)
      if (path.toLowerCase() === here.replace(/[\\/]+$/, '').toLowerCase()) continue
      const log = await $.process
        .run(['git', '-C', path, 'log', '-1', '--format=%ct'], { timeoutMs: 10000 })
        .catch(() => undefined)
      const sec = log?.exitCode === 0 ? parseInt(log.stdout.trim(), 10) : NaN
      candidates.push({ name: entry.name, path, lastCommitSec: Number.isFinite(sec) ? sec : undefined })
    }
    const { picked, skipped } = standupPicks(candidates, Math.floor(Date.now() / 1000), days, STANDUP_MAX)
    if (picked.length === 0) return { text: `No git projects under ${root} have commits in the last ${days} day(s).` }

    const lines: string[] = []
    for (const c of picked) {
      const out = await openWorker($, { folder: c.path, brief: STANDUP_BRIEF, model: 'haiku', read_only: true })
      lines.push('deny' in out ? `  ${c.name}: ${out.deny}` : `  ${c.name} [${out.worker.id}]`)
    }
    if (skipped.length) lines.push(`  (skipped ${skipped.map(c => c.name).join(', ')}: more than ${STANDUP_MAX})`)
    return { text: `Standup: opened ${picked.length} read-only Haiku tab(s) for the last ${days} day(s):\n${lines.join('\n')}` }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const list = await read($, workers)
    const now = Date.now()
    const open = list.filter(w => w.status !== 'closed')
    const total = open.reduce((sum, w) => sum + w.costUsd, 0)
    const working = open.filter(w => w.status === 'working').length
    const needsYou = open.filter(w => w.status === 'needs-you').length
    // Blinking rows show their color on the "on" beats and go grey between.
    const shade = (w: Worker) => (BLINKS.has(w.status) && !blinkOn ? 'gray' : STATUS_COLORS[w.status])
    const act = (w: Worker, run: () => Promise<string>) => () => void run().then(msg => $.ui.toast(msg)).catch(() => undefined)

    if (open.length === 0)
      return (
        <Box flexDirection="column" paddingX={1} paddingY={1}>
          <Text dimColor>No workers open.</Text>
          <Text dimColor italic>Ask the planner, e.g. "check the api project".</Text>
        </Box>
      )

    // One row per worker, so many fit; a second, dim row for what it's waiting
    // on, or its summary (else the last line of its latest reply). A Button's
    // label must be plain text: a styled child makes the whole pane fail to draw.
    return (
      <Box flexDirection="column" paddingX={1}>
        <Box justifyContent="space-between">
          <Text>
            <Text bold>{open.length} open</Text>
            {working > 0 && <Text color={STATUS_COLORS.working}> · {working} working</Text>}
            {needsYou > 0 && <Text bold color={STATUS_COLORS['needs-you']}> · {needsYou} need you</Text>}
          </Text>
          <Text bold color="green">{money(total)}</Text>
        </Box>

        {open.map(w => {
          // What it needs from the user: a permission prompt, or a question it ended on.
          const asking = w.status === 'needs-you' && w.pending !== undefined
          const boxed = w.status === 'needs-you' && !asking && w.box === true
          const questioning = w.status === 'needs-you' && !asking && !boxed && w.question !== undefined
          const urgent = asking || questioning || boxed
          const running = w.background?.length ?? 0
          const latest = w.summary ?? w.lastLine
          const note = asking
            ? `waiting: ${w.pending}`
            : questioning || boxed
              ? `asks: ${w.question}${boxed && !w.choices ? ' (answer it in its tab)' : ''}`
              : running > 0 && w.last === 'turn-end'
                ? `${running} background task${running === 1 ? '' : 's'} still running${latest ? ` · ${latest}` : ''}`
                : latest
          return (
            <Box key={`card-${w.id}`} flexDirection="column" marginTop={1}>
              <Box justifyContent="space-between" gap={1}>
                <Text wrap="truncate-end">
                  <Text color={shade(w)} bold>▌</Text>
                  <Text bold> {w.name}</Text>
                  <Text color={MODEL_COLORS[w.model]}> {w.model}</Text>
                  {w.readOnly && <Text dimColor> read-only</Text>}
                  <Text color={shade(w)} bold={w.status === 'needs-you'} dimColor={w.status === 'starting'}>
                    {'  '}● {STATUS_TEXT[w.status]}
                  </Text>
                </Text>
                <Box gap={1} flexShrink={0}>
                  <Text dimColor>
                    {age(w.startedAt, now)} · {money(w.costUsd)}
                  </Text>
                  {BLINKS.has(w.status) && !urgent && <Button key={`stop-${w.id}`} label="■ stop" variant="primary" onPress={act(w, () => stopWorker($, w))} />}
                  {!BLINKS.has(w.status) && <Button key={`close-${w.id}`} label="close" dimColor onPress={act(w, () => closeAll($, [w]).then(l => l.join('; ')))} />}
                </Box>
              </Box>
              {/* Wrapped, not cut off: a question or a request must be readable here. */}
              {note && (
                <Box paddingLeft={2}>
                  <Text color={urgent ? STATUS_COLORS['needs-you'] : undefined} dimColor={!urgent} italic={!urgent} wrap="wrap">
                    {note}
                  </Text>
                </Box>
              )}
              {/* The answers sit under what they answer, keeping the top row readable. */}
              {urgent && (
                <Box paddingLeft={2} gap={1}>
                  {asking && <Button key={`approve-${w.id}`} label="✓ approve" variant="primary" onPress={act(w, () => answerWorker($, w, 'approve'))} />}
                  {asking && <Button key={`deny-${w.id}`} label="✕ deny" onPress={act(w, () => answerWorker($, w, 'deny'))} />}
                  {boxed &&
                    w.choices?.map((c, i) => (
                      <Button key={`choice-${w.id}-${i}`} label={c.length > 24 ? `${c.slice(0, 23)}…` : c} variant={i === 0 ? 'primary' : undefined} onPress={act(w, () => answerBox($, w, String(i + 1)))} />
                    ))}
                  {questioning && <Button key={`continue-${w.id}`} label="▶ continue" variant="primary" onPress={act(w, () => replyToWorker($, w, 'continue'))} />}
                  {questioning && <Button key={`close-${w.id}`} label="close" dimColor onPress={act(w, () => closeAll($, [w]).then(l => l.join('; ')))} />}
                </Box>
              )}
            </Box>
          )
        })}

        <Box marginTop={1}>
          <Text dimColor italic>costs are API-equivalent estimates</Text>
        </Box>
      </Box>
    )
  })
}

files.hooks/terminals.ts:
// How each terminal app opens a tab or pane that runs a launcher script.
// Pure functions: everything the host is asked to do comes back as argv.

export const TERMINALS = [
  'windows-terminal',
  'tmux',
  'wezterm',
  'kitty',
  'iterm',
  'apple-terminal',
  'gnome-terminal',
  'konsole',
] as const
export type Terminal = (typeof TERMINALS)[number]

export type Env = (name: string) => string | undefined

// Most specific first: inside tmux a "tab" means a tmux window, whatever
// terminal app tmux itself is running in.
export const detect = (env: Env): Terminal | undefined => {
  if (env('TMUX')) return 'tmux'
  if (env('WEZTERM_PANE')) return 'wezterm'
  if (env('KITTY_WINDOW_ID')) return 'kitty'
  if (env('WT_SESSION')) return 'windows-terminal'
  const program = env('TERM_PROGRAM')
  if (program === 'iTerm.app') return 'iterm'
  if (program === 'Apple_Terminal') return 'apple-terminal'
  if (env('KONSOLE_VERSION')) return 'konsole'
  if (env('GNOME_TERMINAL_SCREEN') || env('VTE_VERSION')) return 'gnome-terminal'
  if (env('OS') === 'Windows_NT') return 'windows-terminal'
  return undefined
}

export const isWindows = (terminal: Terminal) => terminal === 'windows-terminal'

// Tab colors by model, so the tab bar shows who is working where.
// By cost: green for the cheapest, red for the most expensive.
export const MODEL_COLORS: Record<string, string> = {
  haiku: '#16A34A',
  sonnet: '#D97706',
  opus: '#DC2626',
  fable: '#991B1B',
}

// --- launcher scripts -------------------------------------------------------

// The modes SPAWN_PANE_MODE may pick for workers. The ones that skip
// permission checks altogether are left out on purpose.
export const WORKER_MODES = ['auto', 'manual', 'acceptEdits'] as const
export type WorkerMode = (typeof WORKER_MODES)[number]

export type Launch = {
  folder: string
  brief: string
  /** Absent: the session's own model (a resumed conversation keeps the one it had). */
  model?: string
  /** `['--session-id', id]` for a new session, `['--resume', id]` to continue one. */
  session: [string, string]
  name: string
  readOnly: boolean
  /** The permission mode of a worker that isn't read-only; Claude Code's default when absent. */
  mode?: WorkerMode
  /** Start it with Remote Control on, named after the worker, to follow it from a phone. */
  remote?: boolean
  worktree?: string
  /** Path prefix for the worker's files: the launcher writes `<base>.pid` and
   *  `<base>.exited`, and looks for `<base>.close`. */
  base: string
}

// Windows PowerShell 5.1 drops embedded double quotes when it hands an
// argument to a native exe, and a line starting with '@ ends the here-string.
export const sanitizePs = (text: string) =>
  text.replace(/"/g, "'").replace(/^'@/gm, " '@").replace(/\\+$/, '')

const HEREDOC = 'SPAWN_PANE_BRIEF'
export const sanitizeSh = (text: string) =>
  text.replace(new RegExp(`^${HEREDOC}$`, 'gm'), ` ${HEREDOC}`)

const psQuote = (s: string) => `'${s.replace(/'/g, "''")}'`
const shQuote = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`

// Plan mode still asks before every shell command. A read-only worker gets
// these looking-only commands without asking, so a status check runs through;
// anything else still asks.
export const READ_ONLY_COMMANDS = [
  'Bash(git status:*)', 'Bash(git log:*)', 'Bash(git diff:*)', 'Bash(git show:*)', 'Bash(git branch:*)', 'Bash(ls:*)',
  // Windows workers run commands through PowerShell, whose rules are spelled this way.
  'PowerShell(git status *)', 'PowerShell(git log *)', 'PowerShell(git diff *)', 'PowerShell(git show *)',
  'PowerShell(git branch *)', 'PowerShell(Get-ChildItem *)', 'PowerShell(Get-Content *)',
]

// Plan mode lets Read, Glob and Grep through without asking, and Claude Code
// always asks about a command chained after a `cd`.
export const READ_ONLY_HINT =
  "You're in read-only mode: look at files with the Read, Glob and Grep tools rather than shell " +
  "commands, and never `cd`: you're already in the right folder."

const claudeArgs = (l: Launch, quote: (s: string) => string) =>
  [
    ...(l.model ? ['--model', l.model] : []),
    // --allowedTools takes every word up to the next flag, so a flag must follow it.
    ...(l.readOnly
      ? ['--permission-mode', 'plan', '--allowedTools', READ_ONLY_COMMANDS.map(quote).join(' ')]
      : l.mode
        ? ['--permission-mode', l.mode]
        : []),
    l.session[0], l.session[1],
    '--name', quote(l.name),
    ...(l.remote ? ['--remote-control', quote(l.name)] : []),
    // Settings that mark the moment the worker shows a permission prompt.
    '--settings', quote(`${l.base}.settings.json`),
    ...(l.worktree ? ['--worktree', quote(l.worktree)] : []),
  ].join(' ')

// The worker's extra settings: a Notification hook that writes `<base>.asking`
// when Claude shows a permission prompt (or a connected tool asks the user
// something). A tool call that is merely taking long looks the same in the
// transcript; this tells the two apart. Claude runs hook commands through a
// shell on every platform.
export const askHookSettings = (base: string, windows: boolean) => {
  // The hook's input (its JSON, with the prompt's message) is the marker's content.
  const marker = `${base}.asking`
  const command = windows
    ? `powershell.exe -NoProfile -Command "[Console]::In.ReadToEnd() | Set-Content -LiteralPath '${marker.replace(/'/g, "''")}'"`
    : `cat > '${marker.replace(/'/g, `'\\''`)}'`
  // PermissionRequest carries the tool and its input; Notification covers a
  // connected tool asking the user something. Neither answers the prompt.
  return JSON.stringify(
    {
      hooks: {
        PermissionRequest: [{ matcher: '*', hooks: [{ type: 'command', command }] }],
        Notification: [{ matcher: 'elicitation_dialog', hooks: [{ type: 'command', command }] }],
      },
    },
    null,
    2,
  )
}

// The planner's Claude gives its child processes these markers, and a new
// terminal tab can inherit them through wt/tmux/osascript. A worker is a
// top-level session of its own: left in place they turn its transcript off
// and hand it the planner's session id and messaging token.
export const INHERITED_MARKERS = [
  'CLAUDECODE', 'CLAUDE_CODE_CHILD_SESSION', 'CLAUDE_CODE_ENTRYPOINT', 'CLAUDE_CODE_EXECPATH',
  'CLAUDE_CODE_MESSAGING_SOCKET', 'CLAUDE_CODE_MESSAGING_TOKEN', 'CLAUDE_CODE_SESSION_ATTENDED',
  'CLAUDE_CODE_SESSION_ID', 'CLAUDE_EFFORT', 'CLAUDE_PID', 'AI_AGENT',
]

export const launcherPs = (l: Launch) =>
  [
    `$base = ${psQuote(l.base)}`,
    'Set-Content -Encoding ascii -LiteralPath "$base.pid" $PID',
    ...INHERITED_MARKERS.map(v => `Remove-Item Env:${v} -ErrorAction SilentlyContinue`),
    ...(l.brief ? ["$brief = @'", sanitizePs(l.brief), "'@"] : []),
    `claude ${claudeArgs(l, psQuote)}${l.brief ? ' $brief' : ''}`,
    'Set-Content -Encoding ascii -LiteralPath "$base.exited" (Get-Date -Format o)',
    // Closed from the planner: end the shell too, so the tab goes away.
    'if (Test-Path -LiteralPath "$base.close") { [Environment]::Exit(0) }',
    '',
  ].join('\r\n')

// After claude exits the tab drops into the user's shell instead of closing,
// unless the planner closed it.
export const launcherSh = (l: Launch) =>
  [
    '#!/bin/sh',
    `base=${shQuote(l.base)}`,
    'echo $$ > "$base.pid"',
    // The tab's own id, so stop_worker can press Esc in it.
    'printf "TMUX_PANE=%s\\nKITTY_WINDOW_ID=%s\\nWEZTERM_PANE=%s\\n" "${TMUX_PANE:-}" "${KITTY_WINDOW_ID:-}" "${WEZTERM_PANE:-}" > "$base.term"',
    `unset ${INHERITED_MARKERS.join(' ')}`,
    `cd ${shQuote(l.folder)} || exit 1`,
    ...(l.brief ? [`brief=$(cat <<'${HEREDOC}'`, sanitizeSh(l.brief), HEREDOC, ')'] : []),
    `claude ${claudeArgs(l, shQuote)}${l.brief ? ' "$brief"' : ''}`,
    'date > "$base.exited"',
    '[ -f "$base.close" ] && exit 0',
    'exec "${SHELL:-/bin/sh}" -l',
    '',
  ].join('\n')

// --- opening the tab or pane --------------------------------------------------

export type Open = {
  terminal: Terminal
  folder: string
  script: string
  asPane: boolean
  wtPath: string
  title: string
  color?: string
}

export type Plan = { argv: string[]; asPane: boolean; note?: string }

// wt treats ';' as its own command separator.
const wtArg = (s: string) => s.replace(/;/g, '\\;')

// Windows Terminal always switches to a tab it opens, so a key pressed in the
// planner at that moment lands in the new tab (an Enter there approves its
// permission prompt). This runs the wt command, then reselects the tab that was
// selected before, through UI Automation. Nothing changes if the focused window
// isn't a terminal. SPAWN_PANE_FOCUS=new skips it.
export const stayOnTab = (argv: string[]): string[] => [
  'powershell.exe', '-NoProfile', '-NonInteractive', '-Command',
  "$a = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('" + base64Utf8(JSON.stringify(argv)) + "')) | ConvertFrom-Json; " +
    '$before = $null; ' +
    'try { ' +
    'Add-Type -AssemblyName UIAutomationClient, UIAutomationTypes; ' +
    '$w = [Windows.Automation.AutomationElement]::FocusedElement; ' +
    '$up = [Windows.Automation.TreeWalker]::ControlViewWalker; ' +
    "while ($w -and $w.Current.ClassName -ne 'CASCADIA_HOSTING_WINDOW_CLASS') { $w = $up.GetParent($w) }; " +
    'if ($w) { ' +
    '$tab = New-Object Windows.Automation.PropertyCondition ([Windows.Automation.AutomationElement]::ControlTypeProperty), ([Windows.Automation.ControlType]::TabItem); ' +
    'foreach ($t in $w.FindAll([Windows.Automation.TreeScope]::Descendants, $tab)) { ' +
    'if ($t.GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Current.IsSelected) { $before = $t } } } ' +
    '} catch {}; ' +
    '& $a[0] @($a | Select-Object -Skip 1); $code = $LASTEXITCODE; ' +
    'if ($before) { Start-Sleep -Milliseconds 800; ' +
    'try { $before.GetCurrentPattern([Windows.Automation.SelectionItemPattern]::Pattern).Select() } catch {} }; ' +
    'exit $code',
]

/** The wt command that `stayOnTab` wraps, for tests and messages. */
export const unwrapStay = (argv: readonly string[]): string[] | undefined => {
  const m = /FromBase64String\('([^']+)'\)/.exec(argv[4] ?? '')
  return m ? JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(m[1]!), c => c.charCodeAt(0)))) : undefined
}
const osa = (s: string) => s.replace(/\\/g, '\\\\').replace(/"/g, '\\"')

export const plan = ({ terminal, folder, script, asPane, wtPath, title, color }: Open): Plan => {
  const run = ['sh', script]
  const tabOnly = (argv: string[]): Plan =>
    asPane ? { argv, asPane: false, note: `${terminal} has no split from the command line; opened a tab` } : { argv, asPane }

  switch (terminal) {
    case 'windows-terminal':
      return {
        argv: [
          wtPath, '-w', '0', ...(asPane ? ['split-pane', '-V'] : ['new-tab']),
          '--title', wtArg(title), '--suppressApplicationTitle', ...(color ? ['--tabColor', color] : []),
          '-d', wtArg(folder),
          'powershell.exe', '-NoExit', '-ExecutionPolicy', 'Bypass', '-File', wtArg(script),
        ],
        asPane,
      }
    case 'tmux':
      return {
        argv: asPane
          ? ['tmux', 'split-window', '-h', '-c', folder, ...run]
          : ['tmux', 'new-window', '-n', title, '-c', folder, ...run],
        asPane,
      }
    case 'wezterm':
      return {
        argv: asPane
          ? ['wezterm', 'cli', 'split-pane', '--right', '--cwd', folder, '--', ...run]
          : ['wezterm', 'cli', 'spawn', '--cwd', folder, '--', ...run],
        asPane,
      }
    case 'kitty':
      return {
        argv: [
          'kitty', '@', 'launch', `--type=${asPane ? 'window' : 'tab'}`,
          asPane ? `--title=${title}` : `--tab-title=${title}`, '--cwd', folder, ...run,
        ],
        asPane,
      }
    case 'iterm': {
      const command = `sh ${shQuote(script)}`
      const verb = asPane
        ? `tell current session of current window to split vertically with default profile command "${osa(command)}"`
        : `tell current window to create tab with default profile command "${osa(command)}"`
      return { argv: ['osascript', '-e', `tell application "iTerm2" to ${verb}`], asPane }
    }
    case 'apple-terminal': {
      // Terminal.app's scripting can only open a tab through simulated
      // keystrokes (an Accessibility grant), so it opens a window instead.
      const command = `sh ${shQuote(script)}`
      return {
        argv: ['osascript', '-e', `tell application "Terminal" to do script "${osa(command)}"`],
        asPane: false,
        note: 'Terminal.app opens a new window rather than a tab',
      }
    }
    case 'gnome-terminal':
      return tabOnly(['gnome-terminal', '--tab', `--working-directory=${folder}`, '--', ...run])
    case 'konsole':
      // `konsole` stays in the foreground until its window closes, so it is
      // started in the background (folder and script passed as arguments,
      // never spliced into the shell text).
      return tabOnly([
        'sh', '-c', 'konsole --new-tab --workdir "$1" -e sh "$2" >/dev/null 2>&1 &', 'spawn-pane', folder, script,
      ])
  }
}

// Ends a worker's claude (the launcher's children) so its launcher sees the
// close marker and exits cleanly.
export const killChildren = (terminal: Terminal, pid: string): string[] =>
  isWindows(terminal)
    ? [
        'powershell.exe', '-NoProfile', '-Command',
        `Get-CimInstance Win32_Process -Filter 'ParentProcessId=${Number(pid)}' | ` +
          'ForEach-Object { taskkill /PID $_.ProcessId /T /F | Out-Null }',
      ]
    : ['pkill', '-TERM', '-P', String(Number(pid))]

// Stopping a worker presses Esc in its tab, as the user would: Claude ends
// the current turn and the session stays open. Windows attaches to the
// worker's console and writes the keypress into its input; tmux, kitty and
// WezTerm address the tab by the id its launcher recorded (`<base>.term`).
// Other terminals have no way to type into a tab from outside.
export const PRESS_ESC_CS =
  'using System; using System.Runtime.InteropServices;' +
  'public static class SpawnPaneEsc {' +
  '[DllImport("kernel32.dll")] public static extern bool FreeConsole();' +
  '[DllImport("kernel32.dll")] public static extern bool AttachConsole(uint pid);' +
  '[DllImport("kernel32.dll", CharSet = CharSet.Unicode)] public static extern IntPtr CreateFile(string n, uint a, uint s, IntPtr sa, uint m, uint f, IntPtr t);' +
  '[StructLayout(LayoutKind.Explicit, CharSet = CharSet.Unicode)] public struct Key {' +
  '[FieldOffset(0)] public ushort EventType; [FieldOffset(4)] public int KeyDown; [FieldOffset(8)] public ushort Repeat;' +
  '[FieldOffset(10)] public ushort VirtualKey; [FieldOffset(12)] public ushort ScanCode; [FieldOffset(14)] public char Char;' +
  '[FieldOffset(16)] public uint Controls; }' +
  '[DllImport("kernel32.dll")] public static extern bool WriteConsoleInput(IntPtr h, Key[] r, uint n, out uint w);' +
  'public static int Press(uint pid, ushort vk, ushort scan, char c) { FreeConsole(); if (!AttachConsole(pid)) return 1;' +
  'IntPtr h = CreateFile("CONIN$", 0xC0000000, 3, IntPtr.Zero, 3, 0, IntPtr.Zero); if (h == new IntPtr(-1)) return 2;' +
  'var down = new Key { EventType = 1, KeyDown = 1, Repeat = 1, VirtualKey = vk, ScanCode = scan, Char = c };' +
  'var up = down; up.KeyDown = 0; uint w; bool ok = WriteConsoleInput(h, new[] { down, up }, 2, out w);' +
  'FreeConsole(); return ok && w == 2 ? 0 : 3; }' +
  // Types text as keystrokes: each character as typed, a carriage return as Enter.
  'public static int Type(uint pid, string text) { FreeConsole(); if (!AttachConsole(pid)) return 1;' +
  'IntPtr h = CreateFile("CONIN$", 0xC0000000, 3, IntPtr.Zero, 3, 0, IntPtr.Zero); if (h == new IntPtr(-1)) return 2;' +
  'var keys = new System.Collections.Generic.List<Key>(); foreach (char c in text) {' +
  'bool enter = c == (char)13; var down = new Key { EventType = 1, KeyDown = 1, Repeat = 1,' +
  'VirtualKey = (ushort)(enter ? 0x0D : 0), ScanCode = (ushort)(enter ? 0x1C : 0), Char = c };' +
  'var up = down; up.KeyDown = 0; keys.Add(down); keys.Add(up); }' +
  'uint w; bool ok = WriteConsoleInput(h, keys.ToArray(), (uint)keys.Count, out w);' +
  'FreeConsole(); return ok && w == keys.Count ? 0 : 3; } }'

// Base64 of the text's UTF-8 bytes: how typed text reaches PowerShell without
// any quoting to get wrong.
const base64Utf8 = (text: string) => btoa(Array.from(new TextEncoder().encode(text), b => String.fromCharCode(b)).join(''))

// Types a reply into a worker's tab and presses Enter, as the user would.
export const typeTextArgv = (terminal: Terminal, pid: string, ids: TabIds, text: string): string[] | undefined => {
  const line = text.replace(/[\r\n]+/g, ' ').trim()
  switch (terminal) {
    case 'windows-terminal':
      return [
        'powershell.exe', '-NoProfile', '-Command',
        `Add-Type -TypeDefinition '${PRESS_ESC_CS}'; ` +
          `$t = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('${base64Utf8(line + '\r')}')); ` +
          `[Environment]::Exit([SpawnPaneEsc]::Type(${Number(pid)}, $t))`,
      ]
    case 'tmux':
      return ids.TMUX_PANE ? ['tmux', 'send-keys', '-t', ids.TMUX_PANE, '-l', line, ';', 'send-keys', '-t', ids.TMUX_PANE, 'Enter'] : undefined
    case 'kitty':
      return ids.KITTY_WINDOW_ID ? ['kitty', '@', 'send-text', '--match', `id:${ids.KITTY_WINDOW_ID}`, line + '\r'] : undefined
    case 'wezterm':
      return ids.WEZTERM_PANE ? ['wezterm', 'cli', 'send-text', '--pane-id', ids.WEZTERM_PANE, '--no-paste', line + '\r'] : undefined
    default:
      return undefined
  }
}

export type TabIds = { TMUX_PANE?: string; KITTY_WINDOW_ID?: string; WEZTERM_PANE?: string }

export const parseTabIds = (text: string): TabIds =>
  Object.fromEntries(
    text.split(/\r?\n/).map(l => l.split('=')).filter(([k, v]) => k && v).map(([k, v]) => [k!.trim(), v!.trim()]),
  )

// Answers a question box: `pick` is a choice's number key; with `type`, that
// number opened "type something", and after a moment for it to open, the text
// is typed and sent with Enter.
export const answerBoxArgv = (
  terminal: Terminal, pid: string, ids: TabIds, keys: { pick: string; type?: string },
): string[] | undefined => {
  const text = keys.type?.replace(/[\r\n]+/g, ' ').trim()
  switch (terminal) {
    case 'windows-terminal':
      return [
        'powershell.exe', '-NoProfile', '-Command',
        `Add-Type -TypeDefinition '${PRESS_ESC_CS}'; ` +
          `$r = [SpawnPaneEsc]::Type(${Number(pid)}, '${keys.pick.replace(/'/g, "''")}'); ` +
          (text
            ? `if ($r -eq 0) { Start-Sleep -Milliseconds 600; ` +
              `$t = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('${base64Utf8(text + '\r')}')); ` +
              `$r = [SpawnPaneEsc]::Type(${Number(pid)}, $t) }; `
            : '') +
          '[Environment]::Exit($r)',
      ]
    case 'tmux':
      return ids.TMUX_PANE
        ? ['tmux', 'send-keys', '-t', ids.TMUX_PANE, '-l', keys.pick,
            ...(text ? [';', 'run-shell', 'sleep 0.6', ';', 'send-keys', '-t', ids.TMUX_PANE, '-l', text, ';', 'send-keys', '-t', ids.TMUX_PANE, 'Enter'] : [])]
        : undefined
    case 'kitty':
      return ids.KITTY_WINDOW_ID
        ? ['sh', '-c', 'kitty @ send-text --match "id:$1" "$2" && { [ -z "$3" ] || { sleep 0.6; kitty @ send-text --match "id:$1" "$3"; }; }',
            'sh', ids.KITTY_WINDOW_ID, keys.pick, text ? text + '\r' : '']
        : undefined
    case 'wezterm':
      return ids.WEZTERM_PANE
        ? ['sh', '-c', 'wezterm cli send-text --pane-id "$1" --no-paste "$2" && { [ -z "$3" ] || { sleep 0.6; wezterm cli send-text --pane-id "$1" --no-paste "$3"; }; }',
            'sh', ids.WEZTERM_PANE, keys.pick, text ? text + '\r' : '']
        : undefined
    default:
      return undefined
  }
}

// The keys the dashboard presses in a worker's tab: Esc stops it (or declines a
// permission prompt); Enter accepts a prompt's highlighted first answer, Yes.
export type TabKey = 'escape' | 'enter'
const KEYS: Record<TabKey, { vk: number; scan: number; char: number; tmux: string; kitty: string; text: string }> = {
  escape: { vk: 0x1b, scan: 0x01, char: 27, tmux: 'Escape', kitty: 'escape', text: '\u001b' },
  enter: { vk: 0x0d, scan: 0x1c, char: 13, tmux: 'Enter', kitty: 'enter', text: '\r' },
}

export const pressKeyArgv = (terminal: Terminal, pid: string, ids: TabIds, key: TabKey): string[] | undefined => {
  const k = KEYS[key]
  switch (terminal) {
    case 'windows-terminal':
      return [
        'powershell.exe', '-NoProfile', '-Command',
        `Add-Type -TypeDefinition '${PRESS_ESC_CS}'; ` +
          `[Environment]::Exit([SpawnPaneEsc]::Press(${Number(pid)}, ${k.vk}, ${k.scan}, [char]${k.char}))`,
      ]
    case 'tmux':
      return ids.TMUX_PANE ? ['tmux', 'send-keys', '-t', ids.TMUX_PANE, k.tmux] : undefined
    case 'kitty':
      return ids.KITTY_WINDOW_ID ? ['kitty', '@', 'send-key', '--match', `id:${ids.KITTY_WINDOW_ID}`, k.kitty] : undefined
    case 'wezterm':
      return ids.WEZTERM_PANE ? ['wezterm', 'cli', 'send-text', '--pane-id', ids.WEZTERM_PANE, '--no-paste', k.text] : undefined
    default:
      return undefined
  }
}

export const interruptArgv = (terminal: Terminal, pid: string, ids: TabIds) => pressKeyArgv(terminal, pid, ids, 'escape')

// Every brief spawn-pane has ever sent says this, so a session that starts
// with it was a worker's, not one the user worked in.
export const WORKER_MARK = 'You were opened in your own terminal'

// Two facts per transcript, from one host command that reads each file named
// on its standard input (one path a line) and prints
// `path<TAB>timestamp<TAB>worker`:
// - timestamp: when Claude last answered there (the last assistant message),
//   looking back 256 KB, then 2 MB, then 8 MB from the end, since large tool
//   output can fill a transcript's end with no answer in it. Resuming a
//   session touches its file without any work, so this, not the file's time,
//   says when it was worked in. Empty when there's none.
// - worker: 1 when the session isn't one the user worked in: its first 64 KB
//   carry WORKER_MARK (a worker's brief), or it ran headless (`claude -p` and
//   the SDKs record an `"entrypoint":"sdk-..."`).
const NOT_USERS = '"entrypoint":"sdk'
export const sessionFactsArgv = (windows: boolean): string[] =>
  windows
    ? [
        'powershell.exe', '-NoProfile', '-Command',
        '[Console]::OutputEncoding=[Text.Encoding]::UTF8;' +
          'foreach ($p in ([Console]::In.ReadToEnd() -split "`r?`n")) { if (-not $p) { continue }; try {' +
          "$f=[IO.File]::Open($p,'Open','Read','ReadWrite');" +
          '$n=[Math]::Min(65536,$f.Length);$b=New-Object byte[] $n;[void]$f.Read($b,0,$n);$h=[Text.Encoding]::UTF8.GetString($b);' +
          `$s=if ($h.Contains('${WORKER_MARK}') -or $h.Contains('${NOT_USERS}')) { '1' } else { '0' };` +
          "$a='';" +
          'foreach ($w in 262144,2097152,8388608) { $n=[Math]::Min($w,$f.Length);[void]$f.Seek(-$n,\'End\');' +
          '$b=New-Object byte[] $n;[void]$f.Read($b,0,$n);$t=[Text.Encoding]::UTF8.GetString($b);' +
          '$m=[regex]::Matches($t,\'"type":"assistant"[^\\n]*?"timestamp":"([^"]+)"\');' +
          'if ($m.Count) { $a=$m[$m.Count-1].Groups[1].Value; break }; if ($n -ge $f.Length) { break } };' +
          '$f.Close(); $p + "`t" + $a + "`t" + $s } catch {} }',
      ]
    : [
        'sh', '-c',
        'while IFS= read -r p; do [ -f "$p" ] || continue; ' +
          `s=0; head -c 65536 "$p" | grep -q -e '${WORKER_MARK}' -e '${NOT_USERS}' && s=1; t=; ` +
          'for w in 262144 2097152 8388608; do ' +
          't=$(tail -c "$w" "$p" 2>/dev/null | grep \'"type":"assistant"\' | tail -n 1 | ' +
          'grep -o \'"timestamp":"[^"]*"\' | tail -n 1 | cut -d\'"\' -f4); ' +
          '[ -n "$t" ] && break; [ "$(wc -c < "$p")" -le "$w" ] && break; done; ' +
          'printf \'%s\\t%s\\t%s\\n\' "$p" "$t" "$s"; done',
      ]

export type SessionFacts = { lastAnswerMs?: number; worker: boolean }

export const parseSessionFacts = (stdout: string) => {
  const out = new Map<string, SessionFacts>()
  for (const line of stdout.split(/\r?\n/)) {
    const [path, iso, worker] = line.split('\t')
    if (!path || worker === undefined) continue
    const ms = iso ? Date.parse(iso) : NaN
    out.set(path, { lastAnswerMs: Number.isFinite(ms) ? ms : undefined, worker: worker.trim() === '1' })
  }
  return out
}

// Every process with its parent and start time (ms since the epoch), one a
// line: `pid ppid startMs`. A permission prompt that was approved shows up as
// a process the worker's Claude started after the prompt appeared (the
// command it was allowed to run), while the transcript stays silent until the
// command ends.
export const processTreeArgv = (windows: boolean): string[] =>
  windows
    ? [
        'powershell.exe', '-NoProfile', '-Command',
        'Get-CimInstance Win32_Process | ForEach-Object { "$($_.ProcessId) $($_.ParentProcessId) ' +
          '$(if ($_.CreationDate) { ([DateTimeOffset]$_.CreationDate).ToUnixTimeMilliseconds() } else { 0 })" }',
      ]
    : ['sh', '-c', 'now=$(date +%s); ps -A -o pid= -o ppid= -o etimes= | while read p pp e; do echo "$p $pp $(( (now - e) * 1000 ))"; done']

export type ProcessInfo = { pid: string; ppid: string; startMs: number }

export const parseProcessTree = (stdout: string) => {
  const children = new Map<string, ProcessInfo[]>()
  for (const line of stdout.split(/\r?\n/)) {
    const [pid, ppid, start] = line.trim().split(/\s+/)
    if (!pid || !ppid || !/^\d+$/.test(pid)) continue
    const info = { pid, ppid, startMs: Number(start) || 0 }
    children.set(ppid, [...(children.get(ppid) ?? []), info])
  }
  return children
}

// Whether anything below `rootPid` started after `sinceMs`.
// Whether `pid` is `rootPid` or runs somewhere below it.
export const isBelow = (tree: Map<string, ProcessInfo[]>, rootPid: string, pid: string): boolean => {
  if (!rootPid) return false
  const queue = [rootPid]
  const seen = new Set<string>()
  while (queue.length) {
    const at = queue.shift()!
    if (at === pid) return true
    if (seen.has(at)) continue
    seen.add(at)
    for (const child of tree.get(at) ?? []) queue.push(child.pid)
  }
  return false
}

export const startedBelow = (tree: Map<string, ProcessInfo[]>, rootPid: string, sinceMs: number) => {
  const queue = [...(tree.get(rootPid) ?? [])]
  for (let n = 0; queue.length && n < 500; n++) {
    const p = queue.shift()!
    if (p.startMs > sinceMs) return true
    queue.push(...(tree.get(p.pid) ?? []))
  }
  return false
}

// Lists the running process ids, to notice workers whose tab was closed by hand.
export const listPids = (windows: boolean): string[] =>
  windows ? ['tasklist', '/FO', 'CSV', '/NH'] : ['ps', '-A', '-o', 'pid=']

export const parsePids = (windows: boolean, stdout: string) =>
  new Set(
    stdout
      .split(/\r?\n/)
      .map(line => (windows ? line.split('","')[1] : line.trim()))
      .filter((pid): pid is string => !!pid && /^\d+$/.test(pid)),
  )

export const SETUP_HINTS: Partial<Record<Terminal, string>> = {
  kitty: 'kitty needs `allow_remote_control yes` in kitty.conf',
  iterm: 'macOS asks once to let Claude Code control iTerm2',
  'apple-terminal': 'macOS asks once to let Claude Code control Terminal',
}

files.hooks/workers.ts:
// What spawn-pane knows about the agents it opened, and how it reads their
// progress back out of Claude Code's own transcripts. Pure functions.

import type { SpawnPaneStatus, SpawnPaneWorker } from '../types'

export type Worker = SpawnPaneWorker
export type Status = SpawnPaneStatus

// Claude Code keeps each session at <config>/projects/<cwd, every
// non-alphanumeric character turned into '-'>/<session id>.jsonl.
export const projectDirName = (cwd: string) => cwd.replace(/[^A-Za-z0-9]/g, '-')

export const SUMMARY_MARK = 'SUMMARY:'

export const reportInstruction = () =>
  `Whenever you finish a task, for this one and any the user gives you later, end ` +
  `your reply with one line that starts with "${SUMMARY_MARK}" and sums up, in under ` +
  `30 words, what you found or did and anything that needs the user's attention.`

// The question a reply ends on, if it ends on one: the last paragraph, when
// its last line ends with a question mark (markdown and closing quotes aside).
export const endingQuestion = (text: string) => {
  const paragraphs = text.trim().split(/\n\s*\n/)
  const last = paragraphs.at(-1)?.trim() ?? ''
  const lastLine = last.split('\n').at(-1)?.replace(/[*_`"')\]\s]+$/, '') ?? ''
  if (!lastLine.endsWith('?')) return undefined
  const plain = last.replace(/[*_`]/g, '').replace(/\s*\n\s*/g, ' ').trim()
  return plain.length > 400 ? `${plain.slice(0, 399)}…` : plain
}

// What a tool call is about, in a few words: the command, the file, the URL.
export const describeToolCall = (name: string, input: Record<string, unknown> | undefined) => {
  const questions = input?.questions
  if (name === 'AskUserQuestion' && Array.isArray(questions) && typeof questions[0]?.question === 'string')
    return `asks: ${questions[0].question}`
  const pick = (...keys: string[]) => keys.map(k => input?.[k]).find(v => typeof v === 'string') as string | undefined
  // A command's own description ("Run the test suite") reads better than the command.
  const detail = pick('description', 'command', 'file_path', 'notebook_path', 'url', 'pattern', 'query', 'prompt')
  const short = detail?.replace(/\s+/g, ' ').trim()
  // A file path shows its file name; a URL or a command stays as it is.
  const isPath = short !== undefined && /[\\/]/.test(short) && !/\s/.test(short) && !short.includes('://')
  const shown = isPath ? short.split(/[\\/]/).pop() : short
  return shown ? `${name} · ${shown.length > 60 ? `${shown.slice(0, 59)}…` : shown}` : name
}

// The last non-empty line of a reply, for "where it left off" when the
// worker wrote no SUMMARY line.
export const lastLineOf = (text: string) => {
  const line = text.split('\n').map(l => l.trim()).filter(Boolean).at(-1)
  const plain = line?.replace(/^[#>*\-\s]+/, '').replace(/[*_`]/g, '')
  return plain ? (plain.length > 140 ? `${plain.slice(0, 139)}…` : plain) : undefined
}

// Per million tokens: [input, output, cache read]. Cache writes are 1.25x input.
const PRICES: [prefix: string, prices: [number, number, number]][] = [
  ['claude-fable-5', [10, 50, 0.25]],
  ['claude-mythos-5', [10, 50, 0.25]],
  ['claude-opus-5-5', [4, 20, 0.2]],
  ['claude-opus-5', [5, 25, 0.5]],
  ['claude-opus-4', [5, 25, 0.5]],
  ['claude-sonnet-5', [2, 10, 0.2]],
  ['claude-sonnet-4', [3, 15, 0.3]],
  ['claude-haiku-4', [1, 5, 0.1]],
]

type Usage = {
  input_tokens?: number
  output_tokens?: number
  cache_read_input_tokens?: number
  cache_creation_input_tokens?: number
}

export const priceOf = (model: string, u: Usage) => {
  const found = PRICES.find(([prefix]) => model.startsWith(prefix))
  if (!found) return undefined
  const [input, output, read] = found[1]
  return (
    ((u.input_tokens ?? 0) * input +
      (u.cache_creation_input_tokens ?? 0) * input * 1.25 +
      (u.cache_read_input_tokens ?? 0) * read +
      (u.output_tokens ?? 0) * output) /
    1e6
  )
}

// The family (haiku, sonnet, opus, fable) of the newest real model id in a
// transcript's tail or a settings value, or undefined.
export const modelFamily = (text: string): string | undefined => {
  const ids = [...text.matchAll(/"model"\s*:\s*"([^"]+)"/g)].map(m => m[1]!.toLowerCase())
  const id = ids.reverse().find(i => /haiku|sonnet|opus|fable|mythos/.test(i))
  return id?.match(/haiku|sonnet|opus|fable/)?.[0] ?? (id ? 'fable' : undefined)
}

// How long a resumed worker may stay silent before it's taken to be sitting
// idle at its prompt: resuming writes nothing to the transcript.
export const RESUME_IDLE_MS = 15000

// A worker's running count, kept on its record so the transcript is read only
// from where the last read stopped (transcripts grow past what one read may
// take, and a resumed worker counts only what it adds itself).
export type Tally = {
  /** Bytes of the transcript already counted. */
  offset: number
  tokens: number
  costUsd: number
  /** The last message id counted: a message is written once per content block. */
  lastId?: string
  last?: 'assistant-tool' | 'assistant-text' | 'user' | 'turn-end'
  summary?: string
  /** The last line of the latest reply, shown when there's no SUMMARY line. */
  lastLine?: string
  /** The tool call it's waiting on, while one is unanswered. */
  pending?: string
  /** The question its latest reply ended on, until the user answers. */
  question?: string
  /** Background agents and commands it started that haven't reported back. */
  background?: string[]
}

// A background task's end, as Claude tells the session about it.
const TASK_DONE = /<task-notification>[\s\S]*?<task-id>([^<]+)<\/task-id>[\s\S]*?<status>([^<]+)<\/status>/g

// The ids of background work an entry starts (a backgrounded command, an async
// agent) and ends (a task notification with a status), if any.
// The ids of background work an entry starts (a backgroundTaskId command, an
// async agent) and ends. Ends are found anywhere in the line: Claude records a
// task's notification as a queued message, an attachment or a user message,
// depending on whether the session was busy when it came.
const backgroundChanges = (entry: any, line: string): { started: string[]; ended: string[] } => {
  const started: string[] = []
  const ended: string[] = []
  const result = entry.toolUseResult
  if (result && typeof result === 'object') {
    if (typeof result.backgroundTaskId === 'string') started.push(result.backgroundTaskId)
    if (result.status === 'async_launched' && typeof result.agentId === 'string') started.push(result.agentId)
  }
  if (line.includes('<task-notification>'))
    for (const m of line.matchAll(TASK_DONE)) if (m[2]!.trim() !== 'running') ended.push(m[1]!.trim())
  return { started, ended }
}

// Claude passing the session a task's end or an agent's report, not the user.
const isNotice = (content: unknown) =>
  typeof content === 'string' &&
  (content.includes('<task-notification>') || content.includes('<agent-message') ||
    content.startsWith('Another Claude session sent a message'))

export const emptyTally = (offset = 0): Tally => ({ offset, tokens: 0, costUsd: 0 })

const utf8Length = (s: string) => new TextEncoder().encode(s).length

// Counts the complete lines of `chunk` (the transcript from `t.offset` on);
// a line still being written is left for the next read.
export const tallyChunk = (t: Tally, chunk: string): Tally => {
  const end = chunk.lastIndexOf('\n') + 1
  if (end === 0) return t
  const next: Tally = { ...t, offset: t.offset + utf8Length(chunk.slice(0, end)) }

  for (const line of chunk.slice(0, end).split('\n')) {
    if (!line.trim()) continue
    let entry: any
    try {
      entry = JSON.parse(line)
    } catch {
      continue
    }
    if (entry.isSidechain) continue
    if (entry.type === 'system' && entry.subtype === 'turn_duration') next.last = 'turn-end'
    const { started, ended } = backgroundChanges(entry, line)
    if (started.length || ended.length)
      next.background = [...(next.background ?? []).filter(id => !ended.includes(id)), ...started.filter(id => !ended.includes(id))]
    // A task notification is Claude telling the session, not the user answering.
    if (entry.type === 'user' && !isNotice(entry.message?.content)) {
      next.last = 'user'
      next.pending = undefined // a tool result (or a new prompt) answers whatever was waiting
      next.question = undefined
    }

    if (entry.type === 'assistant' && entry.message) {
      const m = entry.message
      next.last = m.stop_reason === 'tool_use' ? 'assistant-tool' : 'assistant-text'
      for (const block of Array.isArray(m.content) ? m.content : []) {
        if (block?.type === 'tool_use') next.pending = describeToolCall(String(block.name ?? 'tool'), block.input)
        if (block?.type === 'text' && typeof block.text === 'string' && block.text.trim()) {
          next.lastLine = lastLineOf(block.text)
          next.question = endingQuestion(block.text)
          // a SUMMARY belongs to its own reply; an older one doesn't describe a newer turn
          next.summary = undefined
        }
      }
      if (m.id && m.id !== next.lastId && m.usage) {
        next.lastId = m.id
        const u = m.usage as Usage
        next.tokens +=
          (u.input_tokens ?? 0) + (u.output_tokens ?? 0) +
          (u.cache_read_input_tokens ?? 0) + (u.cache_creation_input_tokens ?? 0)
        next.costUsd += priceOf(String(m.model ?? ''), u) ?? 0
      }
      for (const block of Array.isArray(m.content) ? m.content : []) {
        if (block?.type !== 'text' || typeof block.text !== 'string') continue
        const hit = block.text.split('\n').reverse().find((l: string) => l.trim().startsWith(SUMMARY_MARK))
        if (hit) next.summary = hit.trim().slice(SUMMARY_MARK.length).trim()
      }
    }
  }
  return next
}

// Bumped when the counting learns something new: older counts are redone.
export const TALLY_VERSION = 3

// A record from before 0.5.2 has no startOffset, so where its own work began
// is unknown: it counts from now rather than being billed the whole
// conversation it resumed.
export const adoptLegacy = (w: Worker, transcriptSize: number): Worker =>
  w.startOffset !== undefined
    ? w
    : { ...w, startOffset: transcriptSize, offset: transcriptSize, tokens: 0, costUsd: 0, lastId: undefined }

// `idleMs` is how long the transcript has gone unwritten.
// A worker mid-task with nothing written for this long is taken as stuck.
export const STALLED_MS = 3 * 60 * 1000

// `asking`: the worker's hook marked a permission prompt that nothing in the
// transcript has answered since. A tool call without it is still running,
// however long it takes (a test suite, a build).
export const statusOf = (last: Tally['last'], idleMs: number, asking = false): Status =>
  asking
    ? 'needs-you' // a permission prompt on screen
    : last === undefined
      ? 'starting'
      : last === 'turn-end' || (last === 'assistant-text' && idleMs > 5000)
        ? 'waiting'
        : last === 'user' && idleMs > STALLED_MS
          ? 'needs-you' // the model gone quiet mid-turn
          : 'working'

// What a permission prompt asks, from the hook's input that the marker holds
// ("Claude needs your permission to use Bash").
export const promptMessage = (markerText: string) => {
  try {
    const input = JSON.parse(markerText.trim())
    if (typeof input?.tool_name === 'string') return describeToolCall(input.tool_name, input.tool_input)
    const message = input?.message
    return typeof message === 'string' && message.trim() ? message.trim() : undefined
  } catch {
    return undefined
  }
}

// Claude's multiple-choice question box (the AskUserQuestion tool) is a dialog,
// not a permission prompt: it's answered with a choice, not a yes. Its choices
// are kept when it's one question with one answer, the case that can be
// answered from outside: a number key picks a choice, and the number after
// the last choice opens "type something", for any other answer.
export type QuestionBox = { question: string; choices?: string[] }

export const questionBox = (markerText: string): QuestionBox | undefined => {
  try {
    const input = JSON.parse(markerText.trim())
    if (input?.tool_name !== 'AskUserQuestion') return undefined
    const qs = Array.isArray(input.tool_input?.questions) ? input.tool_input.questions : []
    const first = qs[0]
    if (!first || typeof first.question !== 'string') return { question: 'a multiple-choice question' }
    const labels = Array.isArray(first.options) ? first.options.map((o: any) => String(o?.label ?? '')).filter(Boolean) : []
    const single = qs.length === 1 && !first.multiSelect && labels.length > 0 && labels.length < 9
    return { question: qs.length > 1 ? `${first.question} (and ${qs.length - 1} more)` : first.question, choices: single ? labels : undefined }
  } catch {
    return undefined
  }
}

// The keys that answer a question box with `text`: a choice's number when the
// text is a choice (or its number), else "type something" and the text.
export const boxKeys = (choices: string[], text: string): { pick: string; type?: string } => {
  const t = text.trim().toLowerCase()
  const n = Number(t)
  if (Number.isInteger(n) && n >= 1 && n <= choices.length) return { pick: String(n) }
  const i = choices.findIndex(c => c.trim().toLowerCase() === t)
  return i >= 0 ? { pick: String(i + 1) } : { pick: String(choices.length + 1), type: text.trim() }
}

// A finished turn that ended on a question isn't done: it waits for the user.
// Nor is one with background agents or commands still running: it's working.
export const askedQuestion = (status: Status, question: string | undefined, background = 0): Status =>
  status !== 'waiting' ? status : question ? 'needs-you' : background > 0 ? 'working' : status

// A whole transcript at once, as the tests use it.
export const readProgress = (text: string, idleMs: number) => {
  const t = tallyChunk(emptyTally(), text.endsWith('\n') ? text : text + '\n')
  return { status: statusOf(t.last, idleMs), tokens: t.tokens, costUsd: t.costUsd, summary: t.summary }
}

// --- workspace trust ----------------------------------------------------------

// Claude Code keys trust by the git repository root (else the folder) with
// forward slashes, as `git rev-parse --show-toplevel` prints it.
export const trustKey = (path: string) => path.trim().replace(/\\/g, '/').replace(/\/+$/, '')

// Only folders under the user's workspace are trusted without asking, so a
// planner talked into opening some other folder still gets the dialog.
export const isInside = (root: string, folder: string, caseless: boolean) => {
  const norm = (p: string) => (caseless ? trustKey(p).toLowerCase() : trustKey(p))
  return norm(folder).startsWith(norm(root) + '/')
}

// The config with that key trusted, or undefined when it already is.
export const withTrust = (configText: string, key: string): string | undefined => {
  const config = JSON.parse(configText)
  const projects = (config.projects ??= {})
  if (projects[key]?.hasTrustDialogAccepted === true) return undefined
  projects[key] = { ...projects[key], hasTrustDialogAccepted: true }
  return JSON.stringify(config, null, 2)
}

// --- recent projects ---------------------------------------------------------

// Which of Claude Code's per-folder session directories belong to which
// project: the project's own folder and anything under it. A session dir is
// given to the longest project name it starts with, so `Garden-Archive`'s
// sessions don't count for `Garden`.
export const sessionDirsByProject = (projects: string[], sessionDirs: string[]) => {
  const owned = new Map<string, string[]>(projects.map(p => [p, []]))
  const keyed = projects
    .map(p => ({ p, enc: projectDirName(p).toLowerCase() }))
    .sort((a, b) => b.enc.length - a.enc.length)
  for (const dir of sessionDirs) {
    const d = dir.toLowerCase()
    const hit = keyed.find(({ enc }) => d === enc || d.startsWith(enc + '-'))
    if (hit) owned.get(hit.p)!.push(dir)
  }
  return owned
}

export type ProjectActivity = { path: string; lastSessionMs?: number; lastCommitMs?: number }

const ago = (ms: number | undefined, nowMs: number) => (ms === undefined ? undefined : `${age(ms, nowMs)} ago`)

// Most recently used first; folders whose names start with `_` (archives,
// backups) are listed apart at the end.
export const describeProjects = (root: string, items: ProjectActivity[], nowMs: number) => {
  const recent = (a: ProjectActivity) => Math.max(a.lastSessionMs ?? 0, a.lastCommitMs ?? 0)
  const line = (a: ProjectActivity) => {
    const facts = [
      a.lastSessionMs !== undefined && `Claude last answered ${ago(a.lastSessionMs, nowMs)}`,
      a.lastCommitMs !== undefined && `commit ${ago(a.lastCommitMs, nowMs)}`,
    ].filter(Boolean)
    return `${a.path}${facts.length ? `  (${facts.join(', ')})` : '  (no Claude sessions or commits)'}`
  }
  const isAside = (a: ProjectActivity) => /[\\/]_[^\\/]*$/.test(a.path)
  const sorted = [...items].sort((a, b) => recent(b) - recent(a))
  const main = sorted.filter(a => !isAside(a))
  const aside = sorted.filter(isAside)
  return [
    `Projects in ${root}, most recently used first:`,
    ...main.map(line),
    ...(aside.length ? ['', 'Archives and backups:', ...aside.map(line)] : []),
  ].join('\n')
}

// --- /standup ---------------------------------------------------------------

export type Candidate = { name: string; path: string; lastCommitSec?: number }

export const standupPicks = (candidates: Candidate[], nowSec: number, days: number, max: number) => {
  const fresh = candidates
    .filter(c => c.lastCommitSec !== undefined && nowSec - c.lastCommitSec <= days * 86400)
    .sort((a, b) => b.lastCommitSec! - a.lastCommitSec!)
  return { picked: fresh.slice(0, max), skipped: fresh.slice(max) }
}

export const STANDUP_BRIEF =
  'Give the user a short status update on this project: what it is (one line), ' +
  'the current branch and any uncommitted changes, the last few commits, and ' +
  'anything that looks unfinished or broken. Do not change anything.'

// --- display ----------------------------------------------------------------

export const age = (fromMs: number, nowMs: number) => {
  const s = Math.max(0, Math.round((nowMs - fromMs) / 1000))
  if (s < 60) return `${s}s`
  if (s < 3600) return `${Math.round(s / 60)}m`
  if (s < 2 * 86400) return `${Math.round(s / 3600)}h`
  return `${Math.round(s / 86400)}d`
}

export const money = (usd: number) => (usd <= 0 ? '$0' : usd < 0.01 ? '<$0.01' : `$${usd.toFixed(2)}`)

export const tokenCount = (n: number) =>
  n < 1000 ? String(n) : n < 1e6 ? `${(n / 1000).toFixed(n < 1e4 ? 1 : 0)}k` : `${(n / 1e6).toFixed(1)}M`

// The dashboard's colors: green when done and waiting for the user, amber
// while working, red when it needs the user (a permission prompt, or stuck).
export const STATUS_COLORS: Record<Status, string> = {
  starting: 'gray',
  working: '#F59E0B',
  waiting: '#16A34A',
  'needs-you': '#DC2626',
  closed: 'gray',
}

// The statuses whose cards blink to catch the eye.
export const BLINKS = new Set<Status>(['working', 'needs-you'])

export const STATUS_TEXT: Record<Status, string> = {
  starting: 'starting',
  working: 'working',
  waiting: 'done',
  'needs-you': 'needs you',
  closed: 'closed',
}

// One worker as a line of text, for list_workers and the status line.
export const describe = (w: Worker, nowMs: number) =>
  `${w.name} [${w.id}] ${w.model}${w.readOnly ? ' read-only' : ''}${w.worktree ? ` worktree:${w.worktree}` : ''} · ` +
  `${STATUS_TEXT[w.status]} · ${age(w.startedAt, nowMs)} · ${tokenCount(w.tokens)} tok · ${money(w.costUsd)}` +
  (w.status === 'needs-you' && w.pending
    ? `\n    waiting for approval: ${w.pending}`
    : w.status === 'needs-you' && w.box
      ? `\n    asks: ${w.question ?? 'a question'}${w.choices ? ` (choices: ${w.choices.join(' / ')}; or any other answer)` : ' (answer it in its tab)'}`
    : (w.summary ?? w.lastLine)
      ? `\n    ${w.summary ?? w.lastLine}`
      : '')

export const findWorker = (workers: Worker[], key: string) => {
  const k = key.trim().toLowerCase()
  const open = workers.filter(w => w.status !== 'closed')
  return (
    open.find(w => w.id === k) ??
    open.filter(w => w.name.toLowerCase() === k).at(-1) ??
    open.filter(w => w.folder.toLowerCase().endsWith(k)).at(-1)
  )
}

