export type SpawnPaneStatus = 'starting' | 'working' | 'waiting' | 'needs-you' | 'closed'

export type SpawnPaneWorker = {
  /** Short id the planner and the user refer to it by. */
  id: string
  /** The Claude Code session id the worker runs under. */
  sessionId: string
  name: string
  folder: string
  model: string
  readOnly: boolean
  worktree?: string
  terminal: string
  /** Where its launcher, pid and exit marker live. */
  dir: string
  /** Its transcript, once found. */
  transcript?: string
  /** Bytes of the transcript that came before this worker (a resumed conversation's history). */
  startOffset: number
  /** How far the transcript has been counted, and the last message id counted. */
  offset?: number
  lastId?: string
  last?: 'assistant-tool' | 'assistant-text' | 'user' | 'turn-end'
  startedAt: number
  status: SpawnPaneStatus
  tokens: number
  costUsd: number
  summary?: string
  /** The last line of its latest reply, when it wrote no SUMMARY line. */
  lastLine?: string
  /** The tool call it's waiting on (a permission prompt, while it needs the user). */
  pending?: string
  /** The question its last reply ended on, while it waits for the user's answer. */
  question?: string
  /** Background agents and commands it started that haven't reported back. */
  background?: string[]
  /** Which version of the transcript counting produced the numbers above. */
  tallyVersion?: number
  /** A session the user opened themselves, found running and shown; never closed by spawn-pane. */
  adopted?: boolean
  /** The worker's Claude process, from Claude Code's own session file. */
  claudePid?: string
  /** A multiple-choice question box is on screen (`question` holds it). */
  box?: boolean
  /** That box's choices, when it can be answered from outside. */
  choices?: string[]
}

declare module 'claude-code' {
  interface PluginState {
    'spawn-pane': { workers: SpawnPaneWorker[] }
  }
}
